{"command": "cd /tmp/t1 && rm -f out.epub out.html out.tex && python3 - <<'EOF'
import pty, os, sys
def run(cmd):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    out=b""
    while True:
        try:
            d = os.read(fd, 65536)
        except OSError:
            break
        if not d: break
        out += d
    os.waitpid(pid,0)
    return out
o = run(["/workspace/executable","book.book"])
print(repr(o))
EOF"}

