{"command": "cd /tmp && python3 - <<'EOF'
import pty,os,sys,fcntl,termios,struct
def run(cmd, cols=40, rows=20):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp(cmd[0], cmd)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b""
    while True:
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    os.waitpid(pid,0)
    return out.decode()
print(run(["/workspace/executable","--help"],cols=40))
EOF"}

