{"command": "cd /tmp/loc && rm -f out.*; echo "--- -n non-tty:"; /workspace/executable -n book.book 2>&1 >/dev/null; rm -f out.*; echo "--- -n -q non-tty:"; /workspace/executable -n -q book.book 2>&1 >/dev/null; rm -f out.*; echo "--- -q non-tty:"; /workspace/executable -q book.book 2>&1 >/dev/null; rm -f out.*; echo "--- TTY -a:"; python3 - <<'EOF'
import pty,os,re
def run(args, inp=None, cols=80):
    pid, fd = pty.fork()
    if pid == 0:
        os.execvp("/workspace/executable", ["/workspace/executable"]+args)
    fcntl=None
    out=b""
    if inp:
        os.write(fd, inp)
    while True:
        try: d=os.read(fd,65536)
        except OSError: break
        if not d: break
        out+=d
    os.waitpid(pid,0)
    return out.decode(errors='replace')
s=run(["-n","book.book"])
print(repr(s))
EOF"}

