    ("fr", "francais"),
    ("ga", "irish"),
    ("gd", "scottish"),
    ("gl", "galician"),
    ("he", "hebrew"),
    ("hr", "croatian"),
    ("hu", "hungarian"),
    ("id", "indonesian"),
    ("is", "icelandic"),
    ("it", "italian"),
    ("la", "latin"),
    ("ms", "malay"),
    ("nl", "dutch"),
