    ("sq", "albanian"),
    ("sr", "serbian"),
    ("sw", "swedish"),
    ("tr", "turkish"),
    ("uk", "ukrainian"),
];

/// Returns the babel package name for a language code.
pub fn babel(lang: &str) -> &str {
    for (code, name) in LANGS {
        if *code == lang {
            return name;
        }
    }
    "english"
}

/// English defaults for every localized string.
const DEFAULT: &[(&str, &str)] = &[
    ("toc", "Table of contents"),
    ("chapter", "Chapter"),
    ("part", "Part"),
    ("notes", "Notes"),
    ("title", "Title"),
    ("cover", "Cover"),
];

const FRENCH: &[(&str, &str)] = &[
    ("toc", "Table des matières"),
    ("chapter", "Chapitre"),
    ("part", "Partie"),
    ("notes", "Notes"),
    ("title", "Titre"),
    ("cover", "Couverture"),
];

const SPANISH: &[(&str, &str)] = &[
    ("toc", "Índice"),
    ("chapter", "Capítulo"),
    ("part", "Parte"),
    ("notes", "Notas"),
    ("title", "Título"),
    ("cover", "Portada"),
];

const GERMAN: &[(&str, &str)] = &[
    ("toc", "Inhaltsverzeichnis"),
    ("chapter", "Kapitel"),
    ("part", "Teil"),
    ("notes", "Notizen"),
    ("title", "Titel"),
    ("cover", "Titelseite"),
];

const RUSSIAN: &[(&str, &str)] = &[
    ("toc", "Содержание"),
    ("chapter", "Глава"),
    ("part", "Часть"),
    ("notes", "Примечания"),
    ("title", "Заголовок"),
    ("cover", "Обложка"),
];

const CATALAN: &[(&str, &str)] = &[
    ("toc", "Índex"),
    ("chapter", "Capítol"),
    ("part", "Part"),
    ("notes", "Notes"),
    ("title", "Títol"),
    ("cover", "Portada"),
];

/// Holds the strings of a language, with fallback to English.
pub struct Localization {
    lang: &'static str,
}

impl Localization {
    pub fn new(lang: &str) -> Localization {
        let lang = match lang {
            "fr" => "fr",
            "es" => "es",
            "de" => "de",
            "ru" => "ru",
            "ca" => "ca",
            _ => "en",
        };
        Localization { lang }
    }

    /// Returns the localized string for `key`.
    pub fn get(&self, key: &str) -> &'static str {
        let table = match self.lang {
            "fr" => FRENCH,
            "es" => SPANISH,
            "de" => GERMAN,
            "ru" => RUSSIAN,
            "ca" => CATALAN,
            _ => DEFAULT,
        };
        for (k, v) in table {
            if *k == key {
                return v;
            }
        }
        for (k, v) in DEFAULT {
            if *k == key {
                return v;
            }
        }
        ""
    }

    /// French messages; returns `None` if the language isn't French.
    fn fr(&self) -> Option<&'static str> {
        if self.lang == "fr" {
            Some("fr")
        } else {
            None
        }
    }

    // ---- Crowbook error messages -------------------------------------------------
    // (Only French is currently translated; the other languages use English.)

    pub fn could_not_find_file_for(&self, what: &str) -> String {
        if self.fr().is_some() {
            format!("Impossible de trouver le fichier '%s' pour {}", "%s")
        } else {
            format!("Could not find file '{}' for {}", "", "")
        }
    }
}
