//! Runtime localization of Crowbook messages and rendering strings.

/// All known (babel) language names, indexed by the two-letter language code.
pub const LANGS: &[(&str, &str)] = &[
    ("af", "afrikaans"),
    ("bg", "bulgarian"),
    ("ca", "catalan"),
    ("cs", "czech"),
    ("cy", "welsh"),
    ("da", "danish"),
    ("de", "ngerman"),
    ("el", "greek"),
    ("en", "english"),
