    ("fi", "finnish"),
    ("fr", "francais"),
    ("ga", "irish"),
    ("gd", "scottish"),
    ("gl", "galician"),
    ("he", "hebrew"),
    ("hr", "croatian"),
    ("hu", "hungarian"),
    ("id", "indonesian"),
    ("is", "icelandic"),
    ("it", "italian"),
    ("la", "latin"),
    ("ms", "malay"),
    ("nl", "dutch"),
    ("nn", "norsk"),
    ("pl", "polish"),
    ("pt", "portuguese"),
    ("ro", "romanian"),
    ("ru", "russian"),
    ("sk", "slovak"),
    ("sl", "slovene"),
    ("sq", "albanian"),
    ("sr", "serbian"),
    ("sw", "swedish"),
    ("tr", "turkish"),
    ("uk", "ukrainian"),
];

/// Returns the babel package name for a language code.
pub fn babel(lang: &str) -> &str {
    for (code, name) in LANGS {
        if *code == lang {
            return name;
        }
    }
    "english"
}

const DEFAULT: &[(&str, &str)] = &[
    ("toc", "Table of contents"),
    ("chapter", "Chapter"),
    ("part", "Part"),
    ("notes", "Notes"),
    ("title", "Title"),
    ("cover", "Cover"),
];

const FRENCH: &[(&str, &str)] = &[
    ("toc", "Table des matières"),
    ("chapter", "Chapitre"),
    ("part", "Partie"),
    ("notes", "Notes"),
    ("title", "Titre"),
    ("cover", "Couverture"),
];

const SPANISH: &[(&str, &str)] = &[
    ("toc", "Índice"),
    ("chapter", "Capítulo"),
    ("part", "Parte"),
    ("notes", "Notas"),
    ("title", "Título"),
    ("cover", "Portada"),
];

const GERMAN: &[(&str, &str)] = &[
    ("toc", "Inhaltsverzeichnis"),
    ("chapter", "Kapitel"),
    ("part", "Teil"),
    ("notes", "Notizen"),
    ("title", "Titel"),
    ("cover", "Titelseite"),
];

const RUSSIAN: &[(&str, &str)] = &[
    ("toc", "Содержание"),
    ("chapter", "Глава"),
    ("part", "Часть"),
    ("notes", "Примечания"),
    ("title", "Зagolok"),
    ("cover", "Обложка"),
];

const CATALAN: &[(&str, &str)] = &[
    ("toc", "Índex"),
    ("chapter", "Capítol"),
    ("part", "Part"),
    ("notes", "Notes"),
    ("title", "Títol"),
    ("cover", "Portada"),
];

/// Strings of a language, falling back to English.
pub struct Localization {
    lang: String,
    /// Whether this is the *runtime* language (used to translate error messages).
    runtime: bool,
}

impl Localization {
    pub fn new(lang: &str) -> Localization {
        Localization {
            lang: normalize(lang),
            runtime: false,
        }
    }

    /// Creates a runtime localization used to translate Crowbook's own messages.
    pub fn runtime(lang: &str) -> Localization {
        Localization {
            lang: normalize(lang),
            runtime: true,
        }
    }

    pub fn lang(&self) -> &str {
        &self.lang
    }

    pub fn get(&self, key: &str) -> String {
        let table: &[(&str, &str)] = match self.lang.as_str() {
            "fr" => FRENCH,
            "es" => SPANISH,
            "de" => GERMAN,
            "ru" => RUSSIAN,
            "ca" => CATALAN,
            _ => DEFAULT,
        };
        for (k, v) in table {
            if *k == key {
                return (*v).to_string();
            }
        }
        for (k, v) in DEFAULT {
            if *k == key {
                return (*v).to_string();
            }
        }
        String::new()
    }

    // ---- Crowbook error messages -------------------------------------------------
    //
    // Only French is translated at the moment; all other languages use the
    // English wording.

    /// `Could not find file '{file}' for {what}`
    pub fn could_not_find_file(&self, file: &str, what: &str) -> String {
        if self.fr() {
            format!(
                "Impossible de trouveer le file '{}' pour {}",
                file, what
            )
        } else {
            format!("Could not find file '{}' for {}", file, what)
        }
    }

    fn fr(&self) -> bool {
        self.runtime && self.lang == "fr"
    }
}
RSEOF
