import subprocess, os, os.path
F='QQFILEQQ'
def run(args):
    r = subprocess.run(["/workspace/executable"]+args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
    return r.stdout.decode()
os.makedirs('/tmp/gen', exist_ok=True)
def lang_run(l, args):
    return run(["-L",l]+args)

# --- could_not_find_file: three scenarios with the same filename
# book
open('/tmp/gen/c.book','w').write('title: T\n+ %s\n' % F)
b = {}
for l in ('en','fr'):
    b[l] = lang_run(l, ['c.book'])
# image
open('/tmp/gen/i.md','w').write('![i](%s)\n' % F)
open('/tmp/gen/i.book','w').write('title: T\noutput.html: o.html\n+ i.md\n')
for l in ('en','fr'):
    b[l+'_img'] = lang_run(l, ['i.book'])
# cover
open('/tmp/gen/cv.book','w').write('title: T\ncover: %s\noutput.html: o.html\n+ p1.md\n' % F)
for l in ('en','fr'):
    b[l+'_cv'] = lang_run(l, ['cv.book'])
def errmsg(s):
    for line in s.split('\n'):
        if line.startswith('ERROR '):
            return line[6:]
    raise Exception(s)
pref = {}
suf = {}
for l in ('en','fr'):
    parts = []
    for sc in ('', '_img', '_cv'):
        msg = errmsg(b[l+sc])
        assert F in msg, msg
        parts.append(msg)
    # find position of F
    idxs = [m.index(F) for m in parts]
    p = parts[0][:idxs[0]]
    assert all(m[:idxs[0]]==p for m in parts), parts
    s = [m[idxs[0]+len(F):] for m in parts]
    # common prefix of suffixes
    i=0
    while all(len(x)>i and x[i]==s[0][i] for x in s):
        i+=1
    pref[l]=p
    suf[l]=s[0][:i]
    print(l, repr(pref[l]), repr(suf[l]), [x for x in s])
PYEOF"}

