use super::localization_tables::*;

/// All known (babel) language names, indexed by the two-letter language code.
pub const LANGS: &[(&str, &str)] = &[
    ("af", "afrikaans"),
    ("bg", "bulgarian"),
    ("ca", "catalan"),
    ("cs", "czech"),
    ("cy", "welsh"),
    ("da", "danish"),
    ("de", "ngerman"),
    ("el", "greek"),
    ("en", "english"),
    ("eo", "esperanto"),
    ("es", "spanish"),
    ("et", "estonian"),
    ("eu", "basque"),
    ("fi", "finnish"),
    ("fr", "francais"),
    ("ga", "irish"),
    ("gd", "scottish"),
    ("gl", "galician"),
    ("he", "hebrew"),
    ("hr", "croatian"),
    ("hu", "hungarian"),
    ("id", "indonesian"),
    ("is", "icelandic"),
    ("it", "italian"),
    ("la", "latin"),
    ("ms", "malay"),
    ("nl", "dutch"),
    ("nn", "norsk"),
    ("pl", "polish"),
    ("pt", "portuguese"),
    ("ro", "romanian"),
    ("ru", "russian"),
    ("sk", "slovak"),
    ("sl", "slovene"),
    ("sq", "albanian"),
    ("sr", "serbian"),
    ("sw", "swedish"),
    ("tr", "turkish"),
    ("uk", "ukrainian"),
];

/// Returns the babel package name for a language code.
pub fn babel(lang: &str) -> &str {
    for (code, name) in LANGS {
        if *code == lang {
            return name;
        }
    }
    "english"
}

/// Strings of a language, falling back to English.
pub struct Localization {
    lang: String,
}

impl Localization {
    pub fn new(lang: &str) -> Localization {
        Localization { lang: lang.to_string() }
    }

    pub fn lang(&self) -> &str {
        &self.lang
    }

    /// Returns the localized string for `key`.
    pub fn get(&self, key: &str) -> String {
        for (k, v) in table(&self.lang) {
            if *k == key {
                return (*v).to_string();
            }
        }
        for (k, v) in DEFAULT {
            if *k == key {
                return (*v).to_string();
            }
        }
        String::new()
    }

    /// Whether Crowbook's own messages should be printed in French.
    ///
    /// Only French is translated at the moment.
    pub fn is_french(&self) -> bool {
        self.lang == "fr"
    }

    /// Localizes a Crowbook message, substituting `%{name}` placeholders.
    pub fn msg(&self, key: &str, args: &[(&str, String)]) -> String {
'''
post = '''
        let mut result = self.template(key).to_string();
        for (name, value) in args {
            result = result.replace(&format!("%{{{}}}", name), value);
        }
        result
    }
}
'''
