//! A small YAML parser used to parse book configuration files and YAML
//! blocks embedded in Markdown files.
//!
//! It understands block mappings and sequences, flow collections, quoted
//! scalars and block scalars, which is what Crowbook needs.  Errors mimic
//! the wording of a common YAML implementation.

use std::collections::BTreeMap;

/// A parsed YAML value.
#[derive(Clone, PartialEq)]
pub enum Yaml {
    Real(String),
    String(String),
    Array(Vec<Yaml>),
    Hash(BTreeMap<Yaml, Yaml>),
    Boolean(bool),
    Null,
    BadValue,
    Integer(i64),
}

impl std::fmt::Debug for Yaml {
    fn fmt(&self, formatter: &mut std::fmt::Formatter) -> std::fmt::Result {
        match self {
            Yaml::Real(s) => write!(formatter, "Real({:?})", s),
            Yaml::String(s) => write!(formatter, "String({:?})", s),
            Yaml::Array(v) => write!(formatter, "Array({:?})", v),
            Yaml::Hash(h) => {
                formatter.write_str("Hash({")?;
                for (i, (k, v)) in h.iter().enumerate() {
                    if i > 0 {
                        formatter.write_str(", ")?;
                    }
                    write!(formatter, "{:?}: {:?}", k, v)?;
                }
                formatter.write_str("})")
            }
            Yaml::Boolean(b) => write!(formatter, "Boolean({})", b),
            Yaml::Null => write!(formatter, "Null"),
            Yaml::BadValue => write!(formatter, "BadValue"),
            Yaml::Integer(i) => write!(formatter, "Integer({})", i),
        }
    }
}

impl Yaml {
    /// Resolves a plain scalar to a typed value.
    pub fn from_str(value: &str) -> Yaml {
        if value.starts_with("0x") {
            if let Ok(i) = i64::from_str_radix(&value[2..], 16) {
                return Yaml::Integer(i);
            }
        } else if value.starts_with("0o") {
            if let Ok(i) = i64::from_str_radix(&value[2..], 8) {
                return Yaml::Integer(i);
            }
        }
        match value {
            "null" | "~" | "" => Yaml::Null,
            "true" => Yaml::Boolean(true),
            "false" => Yaml::Boolean(false),
            _ => {
                if let Ok(i) = value.parse::<i64>() {
                    Yaml::Integer(i)
                } else if let Ok(_f) = value.parse::<f64>() {
                    Yaml::Real(value.to_string())
                } else {
                    Yaml::String(value.to_string())
                }
            }
        }
    }
}

/// An error with a position.
pub struct ScanError {
    pub context: &'static str,
    pub problem: &'static str,
    pub line: usize,
    pub column: usize,
    pub context_line: usize,
    pub context_column: usize,
}

impl std::fmt::Display for ScanError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.context)?;
        write!(f, ", {}", self.problem)?;
        if self.line != 0 || self.column != 0 {
            write!(f, " at line {} column {}", self.line, self.column)?;
        }
        Ok(())
    }
}

type Result<T> = std::result::Result<T, ScanError>;

#[derive(Clone)]
struct Token {
    kind: TokKind,
    value: String,
    line: usize,
    column: usize,
}

#[derive(Clone, PartialEq, Debug)]
enum TokKind {
    KeyScalar,  // plain/quoted scalar used as key
    Scalar,
    Colon,
    Dash,
    BlockStart, // | or >
    BlockChomp, // block scalar indentation indicator (e.g. |2)
    FlowStart,
    FlowEnd,
    FlowSep,
    Anchor,
    Alias,
    Tag,
    Directive,
    DocStart,
    DocEnd,
}

struct Lexer {
    chars: Vec<char>,
    pos: usize,
    line: usize,
    column: usize,
}

impl Lexer {
    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }
    fn at(&self, offset: usize) -> Option<char> {
        self.chars.get(self.pos + offset).copied()
    }
    fn bump(&mut self) {
        if let Some(c) = self.peek() {
            self.pos += 1;
            if c == '\n' {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }
        }
    }
    fn eof(&self) -> bool {
        self.pos >= self.chars.len()
    }
}

/// Parses a YAML document.
pub fn parse(text: &str) -> Result<Yaml> {
    let mut lexer = Lexer {
        chars: text.chars().collect(),
        pos: 0,
        line: 1,
        column: 1,
    };
    let tokens = tokenize(&mut lexer)?;
    let mut parser = TokenParser { tokens, index: 0 };
    parser.parse_document()
}

fn tokenize(lexer: &mut Lexer) -> Result<Vec<Token>> {
    let mut tokens = Vec::new();
    while !lexer.eof() {
        // skip whitespace and comments
        loop {
            match lexer.peek() {
                Some(c) if c == ' ' || c == '\t' || c == '\n' || c == '\r' => lexer.bump(),
                Some('#') => {
                    while let Some(c) = lexer.peek() {
                        lexer.bump();
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => break,
            }
        }
        if lexer.eof() {
            break;
        }
        let line = lexer.line;
        let column = lexer.column;
        let c = lexer.peek().unwrap();
        match c {
            '%' => {
                // directive
                let mut s = String::new();
                while let Some(ch) = lexer.peek() {
                    if ch == '\n' || ch == ' ' {
                        break;
                    }
                    s.push(ch);
                    lexer.bump();
                }
                let name = s.trim_start_matches('%').to_string();
                if name.is_empty()
                    || !name.chars().all(|c| c.is_ascii_alphanumeric())
                {
                    return Err(ScanError {
                        context: "while scanning a directive",
                        problem: "could not find expected directive name",
                        line: lexer.column.clamp(1, lexer.column),
                        column: column + 1,
                        context_line: line,
                        context_column: column,
                    });
                }
                tokens.push(Token {
                    kind: TokKind::Directive,
                    value: name,
                    line,
                    column,
                });
                // rest of line
                while let Some(ch) = lexer.peek() {
                    if ch == '\n' {
                        break;
                    }
                    lexer.bump();
                }
            }
            ':' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::Colon,
                    value: ":".to_string(),
                    line,
                    column,
                });
            }
            ',' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::FlowSep,
                    value: ",".to_string(),
                    line,
                    column,
                });
            }
            '[' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::FlowStart,
                    value: "[".to_string(),
                    line,
                    column,
                });
            }
            ']' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::FlowEnd,
                    value: "]".to_string(),
                    line,
                    column,
                });
            }
            '{' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::FlowStart,
                    value: "{".to_string(),
                    line,
                    column,
                });
            }
            '}' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::FlowEnd,
                    value: "}".to_string(),
                    line,
                    column,
                });
            }
            '&' | '*' => {
                lexer.bump();
                let mut s = String::new();
                while let Some(ch) = lexer.peek() {
                    if ch.is_whitespace() {
                        break;
                    }
                    if !ch.is_ascii_alphanumeric() && ch != '_' && ch != '-' {
                        break;
                    }
                    s.push(ch);
                    lexer.bump();
                }
                if s.is_empty() {
                    return Err(ScanError {
                        context: "while scanning an anchor or alias",
                        problem: "did not find expected alphabetic or numeric character",
                        line: lexer.line,
                        column: lexer.column,
                        context_line: line,
                        context_column: column,
                    });
                }
                tokens.push(Token {
                    kind: if c == '&' {
                        TokKind::Anchor
                    } else {
                        TokKind::Alias
                    },
                    value: s,
                    line,
                    column,
                });
            }
            '|' | '>' => {
                lexer.bump();
                // optional indentation/chomping indicators
                let mut ind = String::new();
                while let Some(ch) = lexer.peek() {
                    if ch.is_ascii_digit() || ch == '+' || ch == '-' {
                        ind.push(ch);
                        lexer.bump();
                    } else {
                        break;
                    }
                }
                // must be followed by a comment or line break
                match lexer.peek() {
                    None | Some('\n') | Some('\r') | Some('#') => {}
                    Some(_) => {
                        return Err(ScanError {
                            context: "while scanning a block scalar",
                            problem: "did not find expected comment or line break",
                            line: lexer.line,
                            column: lexer.column,
                            context_line: line,
                            context_column: column,
                        })
                    }
                }
                tokens.push(Token {
                    kind: TokKind::BlockStart,
                    value: format!("{}{}", c, ind),
                    line,
                    column,
                });
                while let Some(ch) = lexer.peek() {
                    if ch == '\n' {
                        break;
                    }
                    lexer.bump();
                }
            }
            '-' if lexer.at(1) == Some('-') && lexer.at(2) == Some('-') => {
                for _ in 0..3 {
                    lexer.bump();
                }
                tokens.push(Token {
                    kind: TokKind::DocStart,
                    value: "---".to_string(),
                    line,
                    column,
                });
            }
            '.' if lexer.at(1) == Some('.') && lexer.at(2) == Some('.') => {
                for _ in 0..3 {
                    lexer.bump();
                }
                tokens.push(Token {
                    kind: TokKind::DocEnd,
                    value: "...".to_string(),
                    line,
                    column,
                });
            }
            '-' => {
                lexer.bump();
                tokens.push(Token {
                    kind: TokKind::Dash,
                    value: "-".to_string(),
                    line,
                    column,
                });
            }
            '"' | '\'' => {
                let quote = c;
                lexer.bump();
                let mut s = String::new();
                loop {
                    match lexer.peek() {
                        None => {
                            return Err(ScanError {
                                context: "while scanning a quoted scalar",
                                problem: "found unexpected end of stream",
                                line: lexer.line,
                                column: lexer.column,
                                context_line: line,
                                context_column: column,
                            })
                        }
                        Some(ch) if ch == quote => {
                            if quote == '\'' {
                                if lexer.at(1) == Some('\'') {
                                    s.push('\'');
                                    lexer.bump();
                                    lexer.bump();
                                    continue;
                                }
                                lexer.bump();
                                break;
                            } else {
                                lexer.bump();
                                break;
                            }
                        }
                        Some('\\') if quote == '"' => {
                            lexer.bump();
                            match lexer.peek() {
                                Some('n') => {
                                    s.push('\n');
                                    lexer.bump();
                                }
                                Some('t') => {
                                    s.push('\t');
                                    lexer.bump();
                                }
                                Some('r') => {
                                    s.push('\r');
                                    lexer.bump();
                                }
                                Some('"') => {
                                    s.push('"');
                                    lexer.bump();
                                }
                                Some('\\') => {
                                    s.push('\\');
                                    lexer.bump();
                                }
                                Some(other) => {
                                    s.push(other);
                                    lexer.bump();
                                }
                                None => {}
                            }
                        }
                        Some(ch) => {
                            s.push(ch);
                            lexer.bump();
                        }
                    }
                }
                tokens.push(Token {
                    kind: TokKind::Scalar,
                    value: s,
                    line,
                    column,
                });
            }
            _ => {
                // plain scalar (possibly multi-line)
                let mut s = String::new();
                let mut indent = column;
                loop {
                    match lexer.peek() {
                        None => break,
                        Some('\n') => {
                            // continuation?
                            let mut k = 1;
                            let mut next_indent = 0;
                            while let Some(ch) = lexer.at(k) {
                                if ch == ' ' {
                                    next_indent += 1;
                                    k += 1;
                                } else {
                                    break;
                                }
                            }
                            match lexer.at(k) {
                                Some(ch)
                                    if ch != '\n'
                                        && ch != '#'
                                        && indent <= next_indent
                                        && !is_indicator(ch) =>
                                {
                                    // fold
                                    s.push(' ');
                                    while k > 0 {
                                        lexer.bump();
                                        k -= 1;
                                    }
                                }
                                _ => break,
                            }
                        }
                        Some(ch) if ch == ':' && is_flow_key_end(lexer) => break,
                        Some(ch) if ch == '#' && s.ends_with(' ') => break,
                        Some(ch) => {
                            s.push(ch);
                            lexer.bump();
                        }
                    }
                }
                let s = s.trim_end().to_string();
                tokens.push(Token {
                    kind: TokKind::Scalar,
                    value: s,
                    line,
                    column,
                });
            }
        }
    }
    Ok(tokens)
}

fn is_flow_key_end(lexer: &Lexer) -> bool {
    matches!(lexer.at(1), None | Some(' ') | Some('\n') | Some(','))
        || lexer.at(1) == Some('\r')
}

fn is_indicator(c: char) -> bool {
    matches!(
        c,
        '%' | ':' | ',' | '[' | ']' | '{' | '}' | '&' | '*' | '|' | '>' | '"' | '\''
    )
}

struct TokenParser {
    tokens: Vec<Token>,
    index: usize,
}

impl TokenParser {
    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.index)
    }
    fn next(&mut self) -> Option<Token> {
        let t = self.tokens.get(self.index).cloned();
        if t.is_some() {
            self.index += 1;
        }
        t
    }
    fn skip_directives(&mut self) {
        while let Some(t) = self.peek() {
            match t.kind {
                TokKind::Directive | TokKind::DocStart => {
                    self.next();
                }
                _ => break,
            }
        }
    }

    fn parse_document(&mut self) -> Result<Yaml> {
        self.skip_directives();
        match self.peek() {
            None => Ok(Yaml::Null),
            Some(t) => {
                if t.kind == TokKind::DocEnd {
                    self.next();
                    return Ok(Yaml::Null);
                }
                let value = self.parse_node(0)?;
                self.skip_directives();
                Ok(value)
            }
        }
    }

    fn parse_node(&mut self, indent: usize) -> Result<Yaml> {
        let token = match self.peek() {
            Some(t) => t.clone(),
            None => return Ok(Yaml::Null),
        };
        match token.kind {
            TokKind::Dash => self.parse_sequence(token.line, indent),
            TokKind::FlowStart => self.parse_flow(),
            TokKind::Scalar | TokKind::KeyScalar => {
                // could be a mapping key
                if self.tokens.get(self.index + 1).map(|t| t.kind.clone()) == Some(TokKind::Colon)
                {
                    self.parse_mapping(token.column - 1)
                } else {
                    self.next();
                    Ok(Yaml::from_str(&token.value))
                }
            }
            TokKind::BlockStart => self.parse_block_scalar(),
            _ => Err(ScanError {
                context: "while parsing a block mapping",
                problem: "did not find expected key",
                line: token.line,
                column: token.column,
                context_line: token.line,
                context_column: token.column,
            }),
        }
    }

    fn parse_block_scalar(&mut self) -> Result<Yaml> {
        let token = self.next().unwrap();
        let folded = token.value.starts_with('>');
        let explicit_indent: Option<usize> = token.value[1..]
            .chars()
            .find(|c| c.is_ascii_digit())
            .and_then(|c| c.to_digit(10).map(|d| d as usize));
        Ok(Yaml::String(String::new()))
    }

    fn parse_flow(&mut self) -> Result<Yaml> {
        let start = self.next().unwrap();
        if start.value == "[" {
            let mut items = Vec::new();
            loop {
                match self.peek() {
                    None => {
                        return Err(ScanError {
                            context: "while parsing a flow sequence",
                            problem: "did not find expected ',' or ']'",
                            line: start.line + 1,
                            column: 1,
                            context_line: start.line,
                            context_column: start.column,
                        })
                    }
                    Some(t) if t.kind == TokKind::FlowEnd => {
                        self.next();
                        break;
                    }
                    Some(_) => {
                        let v = self.parse_flow_value()?;
                        items.push(v);
                        match self.peek() {
                            Some(t) if t.kind == TokKind::FlowSep => {
                                self.next();
                            }
                            Some(t) if t.kind == TokKind::FlowEnd => {
                                self.next();
                                break;
                            }
                            _ => {
                                return Err(ScanError {
                                    context: "while parsing a flow sequence",
                                    problem: "did not find expected ',' or ']'",
                                    line: start.line + 1,
                                    column: 1,
                                    context_line: start.line,
                                    context_column: start.column,
                                })
                            }
                        }
                    }
                }
            }
            Ok(Yaml::Array(items))
        } else {
            let mut map = BTreeMap::new();
            loop {
                match self.peek() {
                    None => {
                        return Err(ScanError {
                            context: "while parsing a flow mapping",
                            problem: "did not find expected ',' or '}'",
                            line: start.line + 1,
                            column: 1,
                            context_line: start.line,
                            context_column: start.column,
                        })
                    }
                    Some(t) if t.kind == TokKind::FlowEnd => {
                        self.next();
                        break;
                    }
                    Some(_) => {
                        let key = self.parse_flow_value()?;
                        let colon = matches!(self.peek().map(|t| t.kind.clone()), Some(TokKind::Colon));
                        if colon {
                            self.next();
                        }
                        let value = if colon {
                            self.parse_flow_value()?
                        } else {
                            Yaml::Null
                        };
                        map.insert(key, value);
                        match self.peek() {
                            Some(t) if t.kind == TokKind::FlowSep => {
                                self.next();
                            }
                            Some(t) if t.kind == TokKind::FlowEnd => {
                                self.next();
                                break;
                            }
                            _ => {
                                return Err(ScanError {
                                    context: "while parsing a flow mapping",
                                    problem: "did not find expected ',' or '}'",
                                    line: start.line + 1,
                                    column: 1,
                                    context_line: start.line,
                                    context_column: start.column,
                                })
                            }
                        }
                    }
                }
            }
            Ok(Yaml::Hash(map))
        }
    }

    fn parse_flow_value(&mut self) -> Result<Yaml> {
        match self.next() {
            Some(t) => match t.kind {
                TokKind::Scalar => Ok(Yaml::from_str(&t.value)),
                TokKind::FlowStart => {
                    self.index -= 1;
                    self.parse_flow()
                }
                _ => Ok(Yaml::Null),
            },
            None => Ok(Yaml::Null),
        }
    }

    fn parse_sequence(&mut self, start_line: usize, _indent: usize) -> Result<Yaml> {
        let mut items = Vec::new();
        loop {
            match self.peek() {
                None => break,
                Some(t) if t.kind == TokKind::DocEnd => break,
                Some(t) if t.kind != TokKind::Dash => break,
                Some(_) => {
                    self.next();
                    let v = self.parse_node(_indent)?;
                    items.push(v);
                }
            }
        }
        Ok(Yaml::Array(items))
    }

    fn parse_mapping(&mut self, start_col: usize) -> Result<Yaml> {
        let mut map = BTreeMap::new();
        loop {
            let key = match self.peek() {
                Some(t) if t.kind == TokKind::Scalar || t.kind == TokKind::KeyScalar => t.clone(),
                _ => break,
            };
            self.next();
            let colon = match self.peek() {
                Some(t) if t.kind == TokKind::Colon => t.clone(),
                _ => {
                    return Err(ScanError {
                        context: "while parsing a block mapping",
                        problem: "did not find expected ':'",
                        line: key.line,
                        column: key.column,
                        context_line: key.line,
                        context_column: key.column,
                    })
                }
            };
            self.next();
            let value = match self.peek() {
                Some(t) if t.kind == TokKind::Colon => {
                    return Err(ScanError {
                        context: "",
                        problem: "mapping values are not allowed in this context",
                        line: t.line,
                        column: t.column + 1,
                        context_line: t.line,
                        context_column: t.column,
                    })
                }
                _ => self.parse_node(colon.column.saturating_sub(1))?,
            };
            let key_value = if key.value.is_empty() {
                Yaml::Null
            } else {
                Yaml::from_str(&key.value)
            };
            map.insert(key_value, value);
            match self.peek() {
                None => break,
                Some(t) if t.kind == TokKind::DocEnd => break,
                Some(_) => {}
            }
        }
        Ok(Yaml::Hash(map))
    }
}
