                    Yaml::Integer(i)
                } else if value.parse::<f64>().is_ok() && !value.starts_with("0b") {
                    Yaml::Real(value.to_string())
                } else {
                    Yaml::String(value.to_string())
                }
            }
        }
    }
}

/// An error with a position.
#[derive(Debug, Clone)]
pub struct ScanError {
    pub context: &'static str,
    pub problem: String,
    pub line: usize,
    pub column: usize,
}

impl std::fmt::Display for ScanError {
    fn fmt(&self, f: &mut std::fmt::Formatter) -> std::fmt::Result {
        write!(f, "{}", self.context)?;
        if !self.problem.is_empty() {
            write!(f, ", {}", self.problem)?;
        }
        if self.line != 0 {
            write!(f, " at line {} column {}", self.line, self.column)?;
        }
        Ok(())
    }
}

/// A node of the document, with the line it starts at.
#[derive(Clone)]
pub struct Node {
    pub value: Yaml,
    pub line: usize,
}

pub type YamlResult<T> = std::result::Result<T, ScanError>;

struct Line {
    indent: usize,
    content: String,
    number: usize,
}

/// Parses a YAML document, returning its root node.
pub fn parse(text: &str) -> YamlResult<Node> {
    let mut lines: Vec<Line> = Vec::new();
    for (i, raw) in text.split('\n').enumerate() {
        let raw = raw.trim_end_matches('\r');
        if raw.trim().is_empty() || raw.trim_start().starts_with('#') {
            continue;
        }
        let indent = raw.len() - raw.trim_start().len();
        let mut content = raw.trim_start().to_string();
        // strip trailing comment
        if let Some(pos) = find_comment(&content) {
            content.truncate(pos);
            let content = content.trim_end().to_string();
            lines.push(Line {
                indent,
                content,
                number: i + 1,
            });
        } else {
            lines.push(Line {
                indent,
                content: content.trim_end().to_string(),
                number: i + 1,
            });
        }
    }
    let mut parser = Parser { lines, index: 0 };
    if parser.lines.is_empty() {
        return Ok(Node {
            value: Yaml::Null,
            line: 0,
        });
    }
    let value = parser.parse_block(0, parser.lines[0].indent)?;
    Ok(Node {
        value,
        line: parser.lines.first().map(|l| l.number).unwrap_or(0),
    })
}

/// Finds the position of a comment in a (stripped) line, or None.
fn find_comment(s: &str) -> Option<usize> {
    let bytes: Vec<char> = s.chars().collect();
    let mut in_single = false;
    let mut in_double = false;
    let mut i = 0;
    while i < bytes.len() {
        let c = bytes[i];
        match c {
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => in_double = !in_double,
            '\\' if in_double => i += 1,
            '#' if !in_single && !in_double => {
                if i == 0 || bytes[i - 1].is_whitespace() {
                    return Some(s.chars().take(i).map(|c| c.len_utfk()).sum::<usize>());
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

struct Parser {
    lines: Vec<Line>,
    index: usize,
}

impl Parser {
    fn peek(&self) -> Option<&Line> {
        self.lines.get(self.index)
    }

    /// Parses a block starting at the current line with the given indentation.
    fn parse_block(&mut self, _min_indent: usize, indent: usize) -> YamlResult<Yaml> {
        let line = match self.peek() {
            Some(l) => l.clone(),
            None => return Ok(Yaml::Null),
        };
        if line.content.starts_with("- ") || line.content == "-" {
            self.parse_sequence(indent)
        } else {
            self.parse_mapping(indent)
        }
    }

    fn parse_sequence(&mut self, indent: usize) -> YamlResult<Yaml> {
        let mut items = Vec::new();
        while let Some(line) = self.peek() {
            if line.indent != indent {
                break;
            }
            if !(line.content.starts_with("- ") || line.content == "-") {
                break;
            }
            let number = line.number;
            let rest = line.content[1..].trim_start().to_string();
            let extra = line.content.len() - line.content[1..].trim_start().len() - 1;
            self.index += 1;
            if rest.is_empty() {
                let v = self.parse_block(indent, indent + 1)?;
                items.push(v);
            } else if let Some(p) = rest.find(':') {
                if p > 0 && !rest[p + 1..].starts_with("//") && is_key_value(&rest) {
                    // inline mapping inside sequence item
                    let mut map = BTreeMap::new();
                    let key = rest[..p].trim().to_string();
                    let value = rest[p + 1..].trim().to_string();
                    let v = if value.is_empty() {
                        self.parse_block(indent, indent + 1)?
                    } else {
                        scalar_or_block(&value, self)
                    };
                    map.insert(Yaml::from_str(&key), v);
                    items.push(Yaml::Hash(map));
                } else {
                    items.push(scalar_or_block(&rest, self));
                }
            } else {
                items.push(scalar_or_block(&rest, self));
            }
            let _ = (number, extra);
        }
        Ok(Yaml::Array(items))
    }

    fn parse_mapping(&mut self, indent: usize) -> YamlResult<Yaml> {
        let mut map = BTreeMap::new();
        while let Some(line) = self.peek() {
            if line.indent < indent {
                break;
            }
            if line.indent > indent {
                // continuation of the previous scalar?  treat as error
                let l = line.clone();
                return Err(ScanError {
                    context: "while parsing a block mapping",
                    problem: "did not find expected key".to_string(),
                    line: l.number,
                    column: l.indent + 1,
                });
            }
            let l = line.clone();
            // anchor / alias / directive / block scalar checks
            let first = l.content.chars().next().unwrap_or(' ');
            if first == '*' || first == '&' {
                let name: String = l.content[1..].chars().take_while(|c| !c.is_whitespace()).collect();
                if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric()) {
                    return Err(ScanError {
                        context: "while scanning an anchor or alias",
                        problem: "did not find expected alphabetic or numeric character"
                            .to_string(),
                        line: l.number,
                        column: l.indent + 1,
                    });
                }
                self.index += 1;
                continue;
            }
            if first == '%' {
                let name: String = l.content[1..]
                    .chars()
                    .take_while(|c| !c.is_whitespace())
                    .collect();
                if name.is_empty() || !name.chars().all(|c| c.is_ascii_alphanumeric()) {
                    return Err(ScanError {
                        context: "while scanning a directive",
                        problem: "could not find expected directive name".to_string(),
                        line: l.number,
                        column: l.indent + 2,
                    });
                }
                self.index += 1;
                continue;
            }
            if first == '|' || first == '>' {
                let rest: String = l.content[1..].to_string();
                let ok = rest.is_empty()
                    || rest.chars().all(|c| c.is_ascii_digit() || c == '+' || c == '-');
                if !ok {
                    return Err(ScanError {
                        context: "while scanning a block scalar",
                        problem: "did not find expected comment or line break".to_string(),
                        line: l.number,
                        column: l.indent + 1,
                    });
                }
                self.index += 1;
                let value = self.read_block_scalar(indent, rest.is_empty(), first == '>');
                map.insert(Yaml::String(String::new()), value);
                continue;
            }
            // find the key
            let (key, rest) = match split_key(&l.content) {
                Some((k, r)) => (k, r),
                None => {
                    return Err(ScanError {
                        context: "while parsing a block mapping",
                        problem: "did not find expected key".to_string(),
                        line: l.number,
                        column: l.indent + 1,
                    })
                }
            };
            let value_str = rest.trim().to_string();
            self.index += 1;
            let value = if value_str.is_empty() {
                match self.peek() {
                    Some(next) if next.indent > indent => self.parse_block(indent, next.indent)?,
                    _ => Yaml::Null,
                }
            } else {
                match scalar_or_block(&value_str, self) {
                    Yaml::String(s) if s.is_empty() => Yaml::String(String::new()),
                    v => v,
                }
            };
            // duplicate colon: `a: b: c`
            if value_str.contains(": ") && !value_str.starts_with('"') && !value_str.starts_with('\'')
                && !value_str.starts_with('[')
                && !value_str.starts_with('{')
            {
                let pos = value_str.find(": ").unwrap();
                return Err(ScanError {
                    context: "",
                    problem: "mapping values are not allowed in this context".to_string(),
                    line: l.number,
                    column: l.indent + l.content.len() - value_str.len() + pos + 1,
                });
            }
            let key_value = if key.is_empty() {
                Yaml::Null
            } else {
                Yaml::from_str(&key)
            };
            map.insert(key_value, value);
        }
        Ok(Yaml::Hash(map))
    }

    fn read_block_scalar(&mut self, indent: usize, plain: bool, folded: bool) -> Yaml {
        let mut out = String::new();
        while let Some(line) = self.peek() {
            if line.indent <= indent {
                break;
            }
            if !out.is_empty() {
                if folded {
                    out.push(' ');
                } else {
                    out.push('\n');
                }
            }
            out.push_str(&line.content);
            self.index += 1;
        }
        if plain {
            out
        } else {
            out
        };
        Yaml::String(out)
    }
}

fn scalar_or_block(value: &str, parser: &mut Parser) -> Yaml {
    let value = value.trim();
    if value.starts_with('[') {
        return parse_flow_seq(value);
    }
    if value.starts_with('{') {
        return parse_flow_map(value);
    }
    if value.starts_with('"') || value.starts_with('\'') {
        let q = value.chars().next().unwrap();
        if value.len() >= 2 && value.ends_with(q) {
            return Yaml::String(unescape(&value[1..value.len() - 1], q));
        }
        return Yaml::String(unescape(&value[1..], q));
    }
    Yaml::from_str(value)
}

fn parse_flow_seq(value: &str) -> Yaml {
    let inner = value.trim_start_matches('[').trim_end_matches(']');
    let mut items = Vec::new();
    for part in split_flow(inner) {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        items.push(Yaml::from_str(part));
    }
    Yaml::Array(items)
}

fn parse_flow_map(value: &str) -> Yaml {
    let inner = value.trim_start_matches('{').trim_end_matches('}');
    let mut map = BTreeMap::new();
    for part in split_flow(inner) {
        let part = part.trim();
        if part.is_empty() {
            continue;
        }
        if let Some(p) = part.find(':') {
            let key = part[..p].trim().to_string();
            let value = part[p + 1..].trim().to_string();
            map.insert(Yaml::from_str(&key), Yaml::from_str(&value));
        }
    }
    Yaml::Hash(map)
}

fn split_flow(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0;
    let mut cur = String::new();
    let mut in_s = false;
    let mut in_d = false;
    for c in s.chars() {
        match c {
            '\'' if !in_d => {
                in_s = !in_s;
                cur.push(c)
            }
            '"' if !in_s => {
                in_d = !in_d;
                cur.push(c)
            }
            '[' | '{' if !in_s && !in_d => {
                depth += 1;
                cur.push(c)
            }
            ']' | '}' if !in_s && !in_d => {
                depth -= 1;
                cur.push(c)
            }
            ',' if depth == 0 && !in_s && !in_d => {
                out.push(cur.clone());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        out.push(cur);
    }
    out
}

fn unescape(s: &str, quote: char) -> String {
    if quote == '\'' {
        return s.replace("''", "'");
    }
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('r') => out.push('\r'),
                Some(o) => out.push(o),
                None => {}
            }
        } else {
            out.push(c);
        }
    }
    out
}

/// Splits a line into `key` and the rest, if it looks like a mapping entry.
fn split_key(content: &str) -> Option<(String, String)> {
    let chars: Vec<char> = content.chars().collect();
    let mut i = 0;
    let mut in_s = false;
    let mut in_d = false;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '\'' if !in_d => in_s = !in_s,
            '"' if !in_s => in_d = !in_d,
            '\\' if in_d => i += 1,
            ':' if !in_s && !in_d => {
                if i + 1 >= chars.len() || chars[i + 1] == ' ' || chars[i + 1] == '\t' {
                    let key: String = chars[..i].iter().collect();
                    let rest: String = chars[i + 1..].iter().collect();
                    return Some((key.trim().to_string(), rest));
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

fn is_key_value(s: &str) -> bool {
    split_key(s).is_some()
}
