//! Book configuration: options, their defaults and their conversion.

use super::yaml::{Yaml, ScanError};
use super::options::GROUPS;
use std::path::PathBuf;

/// Where an error or a warning comes from.
#[derive(Clone, Debug, PartialEq)]
pub struct Source {
    pub file: Option<String>,
    pub line: Option<usize>,
}

impl Source {
    pub fn none() -> Source {
        Source {
            file: None,
            line: None,
        }
    }
    pub fn new(file: &str, line: Option<usize>) -> Source {
        Source {
            file: Some(file.to_string()),
            line,
        }
    }
    /// Renders the source as it is displayed at the beginning of an error.
    pub fn to_string(&self) -> String {
        match (self.file.as_ref(), self.line) {
            (Some(f), Some(l)) => format!("{}:{}: ", f, l),
            (Some(f), None) => format!("{}: ", f),
            _ => String::new(),
        }
    }
}

/// The kind of value an option accepts.
#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Str,
    Int,
    Bool,
    List,
}

/// Returns the kind of value expected by an option, if the key is known.
pub fn kind_of(key: &str) -> Option<Kind> {
    for (_group, options) in GROUPS {
        for option in *options {
            if option.key == key {
                return Some(match option.typ {
                    "boolean" => Kind::Bool,
                    "integer" => Kind::Int,
                    "list of strings" => Kind::List,
                    _ => Kind::Str,
                });
            }
        }
    }
    None
}

/// A Crowbook error, either fatal or collected to be shown at the end.
#[derive(Clone, Debug)]
pub struct CrowbookError {
    pub source: Source,
    pub message: String,
    /// Fatal errors are shown immediately and abort the program.
    pub fatal: bool,
}

impl CrowbookError {
    pub fn fatal(source: Source, message: String) -> CrowbookError {
        CrowbookError {
            source,
            message,
            fatal: true,
        }
    }
    pub fn error(source: Source, message: String) -> CrowbookError {
        CrowbookError {
            source,
            message,
            fatal: false,
        }
    }
}

pub type Res<T> = std::result::Result<T, CrowbookError>;

/// The book configuration.
pub struct Config {
    options: Vec<(String, Yaml)>,
    /// The language used by the localization of Crowbook's own messages.
    pub runtime_lang: String,
}

impl Config {
    pub fn new(runtime_lang: &str) -> Config {
        Config {
            options: Vec::new(),
            runtime_lang: runtime_lang.to_string(),
        }
    }

    pub fn localization(&self) -> super::localization::Localization {
        super::localization::Localization::new(&self.runtime_lang)
    }

    /// Sets an option, converting it to the expected type.
    pub fn set(&mut self, key: &str, value: Yaml, source: &Source) -> Res<()> {
        let kind = match kind_of(key) {
            Some(k) => k,
            None => {
                return Err(CrowbookError::error(
                    source.clone(),
                    format!("unrecognized key '{}'", key),
                ))
            }
        };
        let value = match kind {
            Kind::Str => match value {
                Yaml::String(s) => Yaml::String(s),
                other => {
                    return Err(CrowbookError::error(
                        source.clone(),
                        format!(
                            "Expected a string as value for key {}, found {:?}",
                            key, other
                        ),
                    ))
                }
            },
            Kind::Int => match value {
                Yaml::Integer(i) => Yaml::Integer(i),
                other => {
                    return Err(CrowbookError::error(
                        source.clone(),
                        format!(
                            "expected an integer as value for key '{}', found {:?}",
                            key, other
                        ),
                    ))
                }
            },
            Kind::Bool => match value {
                Yaml::Boolean(b) => Yaml::Boolean(b),
                other => {
                    return Err(CrowbookError::error(
                        source.clone(),
                        format!(
                            "expected a boolean as value for key '{}', found {:?}",
                            key, other
                        ),
                    ))
                }
            },
            Kind::List => {
                let list = match value {
                    Yaml::Array(items) => {
                        let mut converted = Vec::new();
                        for item in items {
                            match item {
                                Yaml::String(s) => converted.push(Yaml::String(s)),
                                other => {
                                    return Err(CrowbookError::error(
                                        source.clone(),
                                        format!(
                                            "Expected only strings in the list for key {}, found {:?}",
                                            key, other
                                        ),
                                    ))
                                }
                            }
                        }
                        Yaml::Array(converted)
                    }
                    other => {
                        return Err(CrowbookError::error(
                            source.clone(),
                            format!("Expected a list as value for key {}, found {:?}", key, other),
                        ))
                    }
                };
                list
            }
        };
        self.set_raw(key.to_string(), value);
        Ok(())
    }

    /// Stores an already converted value, replacing a previous one.
    pub fn set_raw(&mut self, key: String, value: Yaml) {
        for entry in self.options.iter_mut() {
            if entry.0 == key {
                entry.1 = value;
                return;
            }
        }
        self.options.push((key, value));
    }

    pub fn get(&self, key: &str) -> Option<&Yaml> {
        self.options
            .iter()
            .find(|(k, _)| k == key)
            .map(|(_, v)| v)
    }

    pub fn get_str(&self, key: &str) -> Option<String> {
        match self.get(key) {
            Some(Yaml::String(s)) => Some(s.clone()),
            _ => None,
        }
    }

    /// Returns a string option, using the default if it isn't set.
    pub fn get_str_or(&self, key: &str, default: &str) -> String {
        self.get_str(key).unwrap_or_else(|| default.to_string())
    }

    /// Returns the path of a path option.
    pub fn get_path(&self, key: &str) -> Option<PathBuf> {
        self.get_str(key).map(PathBuf::from)
    }

    pub fn get_bool(&self, key: &str, default: bool) -> bool {
        match self.get(key) {
            Some(Yaml::Boolean(b)) => *b,
            _ => default,
        }
    }

    pub fn get_opt_bool(&self, key: &str) -> Option<bool> {
        match self.get(key) {
            Some(Yaml::Boolean(b)) => Some(*b),
            _ => None,
        }
    }

    pub fn get_int(&self, key: &str, default: i64) -> i64 {
        match self.get(key) {
            Some(Yaml::Integer(i)) => *i,
            _ => default,
        }
    }

    pub fn get_opt_int(&self, key: &str) -> Option<i64> {
        match self.get(key) {
            Some(Yaml::Integer(i)) => Some(*i),
            _ => None,
        }
    }

    pub fn get_list(&self, key: &str) -> Option<Vec<String>> {
        match self.get(key) {
            Some(Yaml::Array(items)) => Some(
                items
                    .iter()
                    .filter_map(|i| match i {
                        Yaml::String(s) => Some(s.clone()),
                        _ => None,
                    })
                    .collect(),
            ),
            _ => None,
        }
    }

    /// Lists all the options, as shown by `--list-options`.
    pub fn list_options() -> String {
        let mut out = String::new();
        for (group, options) in GROUPS {
            out.push_str(group);
            out.push('\n');
            for option in *options {
                out.push_str(option.key);
                out.push('\n');
                out.push_str(&format!(
                    "  type: {} (default: {})\n",
                    option.typ, option.default
                ));
                out.push_str(&wrap(&option.desc, 80));
                out.push('\n');
            }
        }
        out
    }
}

/// Wraps a text to a maximum width, indenting continuation lines.
pub fn wrap(text: &str, width: usize) -> String {
    let indent = "  ";
    let mut out = String::new();
    let mut line = String::from(indent);
    for word in text.split(' ') {
        if line.len() + word.len() + 1 > width && !line.trim().is_empty() {
            out.push_str(&line);
            out.push('\n');
            line = String::from(indent);
        }
        if line.len() > indent.len() {
            line.push(' ');
        }
        line.push_str(word);
    }
    out.push_str(&line);
    out
}

/// Converts a YAML error into a Crowbook error message.
pub fn yaml_error(source: &Source, error: &ScanError) -> String {
    format!("YAML block was not valid YAML: {}", error)
}
