    pub links: Vec<(String, String, Option<String>)>,
}

/// A line of the source, with its indentation.
#[derive(Clone)]
struct Line {
    indent: usize,
    content: String,
    /// Whether the line ends with a hard break.
    hard: bool,
}

pub struct Parser<'a> {
    lines: Vec<Line>,
    index: usize,
    config: &'a Config,
    superscript: bool,
}

fn is_blank(s: &str) -> bool {
    s.trim().is_empty()
}

/// Removes the indentation of a line, returning `(indent, rest)`.
fn indent_of(s: &str) -> usize {
    s.len() - s.trim_start().len()
}

/// Whether a line ends with a hard break (two spaces or a backslash).
fn hard_break(s: &str) -> bool {
    let trimmed = s.trim_end();
    let trailing = s.len() - trimmed.len();
    if trailing >= 2 {
        return true;
    }
    if trimmed.ends_with('\\') && !trimmed.ends_with("\\\\") {
        return true;
    }
    false
}

impl<'a> Parser<'a> {
    pub fn new(text: &str, config: &'a Config) -> Parser<'a> {
        let superscript = config.get_bool("crowbook.markdown.superscript", false);
        let mut lines = Vec::new();
        for raw in text.split('\n') {
            let raw = raw.trim_end_matches('\r');
            let indent = indent_of(raw);
            let content = raw[indent..].to_string();
            let hard = hard_break(raw);
            lines.push(Line {
                indent,
                content,
                hard,
            });
        }
        Parser {
            lines,
            index: 0,
            config,
            superscript,
        }
    }

    fn peek(&self) -> Option<&Line> {
        self.lines.get(self.index)
    }

    fn at(&self, offset: usize) -> Option<&Line> {
        self.lines.get(self.index + offset)
    }

    fn blank(&self) -> bool {
        self.peek().map(|l| is_blank(&l.content)).unwrap_or(true)
    }

    /// Parses a whole document.
    pub fn parse_document(&mut self) -> Doc {
        let mut doc = Doc::default();
        let blocks = self.parse_blocks(0);
        for block in blocks {
            match block {
                Block::NoteDef { label, blocks } => doc.notes.push((label, blocks)),
                Block::LinkDef {
                    label,
                    url,
                    title,
                } => doc.links.push((label, url, title)),
                other => doc.blocks.push(other),
            }
        }
        doc
    }

    fn parse_blocks(&mut self, min_indent: usize) -> Vec<Block> {
        let mut blocks = Vec::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                self.index += 1;
                continue;
            }
            if line.indent < min_indent {
                break;
            }
            let content = line.content.clone();
            let indent = line.indent;
            // YAML block
            if content == "---" && self.config.get_bool("input.yaml_blocks", false) {
                let yaml = self.read_yaml_block();
                if let Some(y) = yaml {
                    blocks.push(Block::Yaml(y));
                    continue;
                }
            }
            // ATX heading
            if let Some((level, text)) = heading_of(&content) {
                self.index += 1;
                blocks.push(Block::Heading {
                    level,
                    inline: self.parse_inline(&text),
                });
                continue;
            }
            // fenced code
            if content.starts_with("```") || content.starts_with("~~~") {
                let fence = content[..3].to_string();
                let lang = content[3..].trim().to_string();
                let lang = if lang.is_empty() {
                    None
                } else {
                    Some(lang)
                };
                self.index += 1;
                let text = self.read_fenced(&fence, indent);
                blocks.push(Block::Code {
                    lang,
                    text,
                    indented: false,
                });
                continue;
            }
            // indented code
            if indent >= 4 {
                let text = self.read_indented_code(indent);
                blocks.push(Block::Code {
                    lang: None,
                    text,
                    indented: true,
                });
                continue;
            }
            // thematic break or setext heading
            if is_rule(&content) {
                if let Some(prev) = blocks.last() {
                    if let Block::Paragraph(_) = prev {
                        if let Some(next) = self.at(1) {
                            if is_blank(&next.content) || is_rule(&next.content) {
                                // a rule after a paragraph, separated by nothing
                            }
                        }
                        // setext heading
                        let level = if content.starts_with('=') { 1 } else { 2 };
                        self.index += 1;
                        if let Block::Paragraph(p) = blocks.pop().unwrap() {
                            blocks.push(Block::Heading { level, inline: p });
                        }
                        continue;
                    }
                }
                self.index += 1;
                blocks.push(Block::Rule);
                continue;
            }
            // blockquote
            if content.starts_with('>') {
                let blocks2 = self.read_blockquote(indent);
                blocks.push(Block::Quote(blocks2));
                continue;
            }
            // list
            if let Some(item) = list_marker(&content) {
                let list = self.read_list(indent, &item);
                blocks.push(list);
                continue;
            }
            // definition list
            if let Some(next) = self.at(1) {
                if !is_blank(&next.content) && next.content.starts_with(": ") {
                    let dl = self.read_def_list();
                    blocks.push(dl);
                    continue;
                }
            }
            // footnote definition
            if let Some(label) = note_def_label(&content) {
                self.index += 1;
                let mut text = note_def_text(&content).to_string();
                // continuation lines
                while let Some(l) = self.peek() {
                    if is_blank(&l.content) {
                        break;
                    }
                    if l.indent == 0 && (l.content.starts_with("[^") || !l.content.starts_with(' ')) {
                        break;
                    }
                    if !text.is_empty() {
                        text.push(' ');
                    }
                    text.push_str(&l.content);
                    self.index += 1;
                }
                let inner = Parser::new(&text, self.config).parse_document();
                blocks.push(Block::NoteDef {
                    label,
                    blocks: inner.blocks,
                });
                continue;
            }
            // link reference definition
            if let Some((label, url, title)) = link_def(&content) {
                self.index += 1;
                blocks.push(Block::LinkDef { label, url, title });
                continue;
            }
            // table
            if content.starts_with('|') {
                if let Some(table) = self.read_table() {
                    blocks.push(table);
                    continue;
                }
            }
            // paragraph
            let para = self.read_paragraph(min_indent);
            if !para.is_empty() {
                blocks.push(Block::Paragraph(para));
            }
        }
        blocks
    }

    fn read_yaml_block(&mut self) -> Option<String> {
        // the first line was already recognized as '---'
        let start = self.index + 1;
        let mut i = start;
        while let Some(l) = self.lines.get(i) {
            if l.content.trim() == "---" {
                break;
            }
            i += 1;
        }
        if i >= self.lines.len() {
            return None;
        }
        let mut text = String::new();
        for l in &self.lines[start..i] {
            text.push_str(&" ".repeat(l.indent));
            text.push_str(&l.content);
            text.push('\n');
        }
        self.index = i + 1;
        Some(text)
    }

    fn read_fenced(&mut self, fence: &str, _indent: usize) -> String {
        let mut out = String::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if line.content.starts_with(fence)
                && line.content[3..].trim().is_empty()
            {
                self.index += 1;
                break;
            }
            out.push_str(&line.content);
            out.push('\n');
            self.index += 1;
        }
        out
    }

    fn read_indented_code(&mut self, indent: usize) -> String {
        let mut out = String::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                // only continue if the next non-blank line is still indented
                let mut k = self.index;
                while self.lines.get(k).map(|l| is_blank(&l.content)).unwrap_or(false) {
                    k += 1;
                }
                match self.lines.get(k) {
                    Some(l) if l.indent >= 4 => {
                        self.index = k;
                        continue;
                    }
                    _ => break,
                }
            }
            if line.indent < 4 {
                break;
            }
            out.push_str(&line.content[4.min(line.content.len())..]);
            out.push('\n');
            self.index += 1;
        }
        out
    }

    fn read_blockquote(&mut self, _indent: usize) -> Vec<Block> {
        let mut text = String::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                // lazy continuation?
                let mut k = self.index;
                while self.lines.get(k).map(|l| is_blank(&l.content)).unwrap_or(false) {
                    k += 1;
                }
                match self.lines.get(k) {
                    Some(l) if l.content.starts_with('>') => {
                        self.index = k;
                        continue;
                    }
                    _ => break,
                }
            }
            if !line.content.starts_with('>') {
                break;
            }
            let rest = if line.content.len() > 1 {
                if line.content.as_bytes()[1] == b' ' {
                    line.content[2..].to_string()
                } else {
                    line.content[1..].to_string()
                }
            } else {
                String::new()
            };
            text.push_str(&rest);
            text.push('\n');
            self.index += 1;
        }
        Parser::new(&text, self.config).parse_document()
    }

    fn read_paragraph(&mut self, min_indent: usize) -> Vec<Inline> {
        let mut inlines = Vec::new();
        let mut text = String::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                break;
            }
            if line.indent < min_indent {
                break;
            }
            // interrupting constructs
            if heading_of(&line.content).is_some()
                || is_rule(&line.content)
                || line.content.starts_with('>')
                || line.content.starts_with("```")
                || list_marker(&line.content).is_some()
            {
                break;
            }
            if !text.is_empty() {
                if line.hard {
                    inlines.extend(self.parse_inline(&text));
                    inlines.push(Inline::HardBreak);
                    text.clear();
                } else {
                    text.push(' ');
                }
            }
            text.push_str(&line.content);
            self.index += 1;
        }
        if !text.is_empty() {
            inlines.extend(self.parse_inline(&text));
        }
        inlines
    }

    fn read_list(&mut self, indent: usize, first: &Marker) -> Block {
        let mut items: Vec<Vec<Block>> = Vec::new();
        let ordered = first.ordered;
        let mut start = first.number;
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                // a blank line ends the list, unless followed by an indented item
                let mut k = self.index;
                while self
                    .lines
                    .get(k)
                    .map(|l| is_blank(&l.content))
                    .unwrap_or(false)
                {
                    k += 1;
                }
                match self.lines.get(k) {
                    Some(l) if l.indent > indent && list_marker(&l.content).is_some() => {
                        self.index = k;
                        continue;
                    }
                    _ => break,
                }
            }
            let marker = match list_marker(&line.content) {
                Some(m) if m.ordered == ordered && line.indent == indent => m,
                _ => break,
            };
            if marker.ordered {
                start = marker.number;
            }
            self.index += 1;
            let content = line.content[marker.len..].trim_start().to_string();
            let mut blocks = Parser::new(&content, self.config).parse_document();
            // continuation lines (indented more than the marker)
            let extra = Parser::new("", self.config);
            let _ = extra;
            while let Some(l) = self.peek() {
                if is_blank(&l.content) {
                    let mut k = self.index;
                    while self
                        .lines
                        .get(k)
                        .map(|l| is_blank(&l.content))
                        .unwrap_or(false)
                    {
                        k += 1;
                    }
                    match self.lines.get(k) {
                        Some(next)
                            if next.indent > indent
                                && !next.content.starts_with('>')
                                && list_marker(&next.content).is_none() =>
                        {
                            self.index = k;
                            continue;
                        }
                        _ => break,
                    }
                }
                if l.indent <= indent {
                    break;
                }
                // append the line's content to the item
                let last = blocks.len();
                match blocks.last_mut() {
                    Some(Block::Paragraph(p)) => {
                        p.push(Inline::SoftBreak);
                        p.extend(Parser::new(&l.content, self.config).parse_document());
                    }
                    _ => {
                        blocks.push(Block::Paragraph(Parser::new(&l.content, self.config).parse_document()));
                    }
                }
                let _ = last;
                self.index += 1;
            }
            items.push(blocks);
        }
        if ordered {
            Block::Ordered { start, items }
        } else {
            Block::Bullet(items)
        }
    }

    fn read_def_list(&mut self) -> Block {
        let mut entries = Vec::new();
        loop {
            let line = match self.peek() {
                Some(l) => l.clone(),
                None => break,
            };
            if is_blank(&line.content) {
                break;
            }
            if let Some(next) = self.at(1) {
                if next.content.starts_with(": ") || next.content.starts_with(":\t") {
                    self.index += 1;
                    let term = self.parse_inline(&line.content);
                    self.index += 1;
                    let mut text = String::new();
                    loop {
                        let l = match self.peek() {
                            Some(l) => l.clone(),
                            None => break,
                        };
                        if is_blank(&l.content) {
                            break;
                        }
                        if !text.is_empty() {
                            text.push(' ');
                        }
                        text.push_str(&l.content);
                        self.index += 1;
                    }
                    let blocks =
                        Parser::new(&text, self.config).parse_document();
                    entries.push((term, blocks));
                    continue;
                }
            }
            break;
        }
        Block::DefList(entries)
    }

    fn read_table(&mut self) -> Option<Block> {
        let header = match self.peek() {
            Some(l) => l.clone(),
            None => return None,
        };
        let sep = match self.at(1) {
            Some(l) => l.clone(),
            None => return None,
        };
        if !is_separator(&sep.content) {
            return None;
        }
        self.index += 2;
        let head = parse_row(&header.content);
        let mut rows = Vec::new();
        while let Some(line) = self.peek() {
            if is_blank(&line.content) || !line.content.starts_with('|') {
                break;
            }
            rows.push(parse_row(&line.content));
            self.index += 1;
        }
        Some(Block::Table { head, rows })
    }

    // ---- inline parsing -------------------------------------------------------

    pub fn parse_inline(&self, text: &str) -> Vec<Inline> {
        let cleaned = clean(text, self.config);
        parse_inline_text(&cleaned, self.superscript, &self)
    }
}

fn parse_inline_text(
    text: &str,
    superscript: bool,
    _parser: &Parser,
) -> Vec<Inline> {
    let chars: Vec<char> = text.chars().collect();
    let mut out: Vec<Inline> = Vec::new();
    let mut i = 0;
    let mut buf = String::new();
    while i < chars.len() {
        let c = chars[i];
        match c {
            '\\' => {
                if let Some(&next) = chars.get(i + 1) {
                    if is_punct(next) {
                        buf.push(next);
                        i += 2;
                        continue;
                    }
                }
                buf.push('\\');
                i += 1;
            }
            '`' => {
                // code span
                let mut n = 0;
                while chars.get(i + n) == Some(&'`') {
                    n += 1;
                }
                // find a matching run
                let mut j = i + n;
                let mut found = None;
                while j < chars.len() {
                    if chars[j] == '`' {
                        let mut m = 0;
                        while chars.get(j + m) == Some(&'`') {
                            m += 1;
                        }
                        if m == n {
                            found = Some(j);
                            break;
                        }
                        j += m;
                    } else {
                        j += 1;
                    }
                }
                match found {
                    Some(end) => {
                        flush(&mut buf, &mut out);
                        let inner: String = chars[i + n..end].iter().collect();
                        let inner = inner.trim().replace('\n', " ");
                        out.push(Inline::Code(inner));
                        i = end + n;
                    }
                    None => {
                        for _ in 0..n {
                            buf.push('`');
                        }
                        i += n;
                    }
                }
            }
            '*' | '_' | '~' => {
                // emphasis runs
                let mut n = 0;
                while chars.get(i + n) == Some(&c) {
                    n += 1;
                }
                let before = if i == 0 { None } else { Some(chars[i - 1]) };
                let after = chars.get(i + n).copied();
                // try to find a closing run
                let mut close = None;
                if after.is_some() {
                    let mut j = i + n;
                    while j < chars.len() {
                        if chars[j] == c {
                            let mut m = 0;
                            while chars.get(j + m) == Some(&c) {
                                m += 1;
                            }
                            let prev = chars[j - 1];
                            let nxt = chars.get(j + m).copied();
                            let can_close = !prev.is_whitespace()
                                && (c != '_' || !prev.is_alphanumeric() || nxt.is_none() || nxt.map(|x| !x.is_alphanumeric()).unwrap_or(true));
                            if can_close && m <= n {
                                close = Some((j, m));
                                break;
                            }
                            j += m;
                        } else {
                            j += 1;
                        }
                    }
                }
                if let Some((j, m)) = close {
                    let can_close_here = !before
                        .map(|c| c.is_whitespace())
                        .unwrap_or(false);
                    if can_close_here {
                        flush(&mut buf, &mut out);
                        let inner_text: String = chars[i..j].iter().collect();
                        let inner = parse_inline_text(&inner_text, superscript, _parser);
                        let delim = if c == '~' {
                            2
                        } else if m >= 2 {
                            2
                        } else {
                            1
                        };
                        let (outer, rest_len) = if c == '~' {
                            (Inline::Del(inner.clone()), m)
                        } else if m >= 2 {
                            (Inline::Strong(inner.clone()), 2)
                        } else {
                            (Inline::Em(inner.clone()), 1)
                        };
                        let _ = delim;
                        // the opening run is n; the closing run is m
                        if c == '~' {
                            out.push(Inline::Del(inner));
                        } else if n >= 2 {
                            // both strong
                            out.push(Inline::Strong(inner));
                        } else {
                            out.push(Inline::Em(inner));
                        }
                        let _ = (outer, rest_len);
                        i = j + m;
                        continue;
                    }
                }
                for _ in 0..n {
                    buf.push(c);
                }
                i += n;
            }
            '[' => {
                if let Some(len) = try_link(&chars, i, superscript) {
                    flush(&mut buf, &mut out);
                    let (inline, next) = inline_link(&chars, i, superscript);
                    out.push(inline);
                    i = next;
                } else if let Some((label, end)) = note_ref(&chars, i) {
                    flush(&mut buf, &mut out);
                    out.push(Inline::Note(label));
                    i = end;
                } else {
                    buf.push('[');
                    i += 1;
                }
            }
            '!' => {
                if chars.get(i + 1) == Some(&'[') {
                    if let Some((inline, next)) = try_image(&chars, i) {
                        flush(&mut buf, &mut out);
                        out.push(inline);
                        i = next;
                        continue;
                    }
                }
                buf.push('!');
                i += 1;
            }
            '<' => {
                // autolink?
                if let Some((url, end)) = autolink(&chars, i) {
                    flush(&mut buf, &mut out);
                    out.push(Inline::Link {
                        url: url.clone(),
                        title: None,
                        text: vec![Inline::Text(url)],
                    });
                    i = end;
                } else {
                    buf.push('<');
                    i += 1;
                }
            }
            '&' => {
                if let Some((decoded, len)) = entity(&chars, i) {
                    buf.push_str(&decoded);
                    i += len;
                } else {
                    buf.push('&');
                    i += 1;
                }
            }
            '^' | '~' if superscript => {
                // superscript/subscript
                let other = if c == '^' { '~' } else { '^' };
                let mut j = i + 1;
                while j < chars.len() && chars[j] != c && chars[j] != '\n' {
                    j += 1;
                }
                if j < chars.len() && chars[j] == c && j > i + 1 {
                    flush(&mut buf, &mut out);
                    let inner_text: String = chars[i + 1..j].iter().collect();
                    let inner = parse_inline_text(&inner_text, superscript, _parser);
                    if c == '^' {
                        out.push(Inline::Sup(inner));
                    } else {
                        out.push(Inline::Sub(inner));
                    }
                    i = j + 1;
                } else {
                    buf.push(c);
                    i += 1;
                }
            }
            _ => {
                buf.push(c);
                i += 1;
            }
        }
    }
    flush(&mut buf, &mut out);
    out
}

fn flush(buf: &mut String, out: &mut Vec<Inline>) {
    if !buf.is_empty() {
        out.push(Inline::Text(buf.clone()));
        buf.clear();
    }
}

fn is_punct(c: char) -> bool {
    "!\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~".contains(c)
}

fn heading_of(content: &str) -> Option<(usize, String)> {
    let n = content.chars().take_while(|&c| c == '#').count();
    if n == 0 || n > 6 {
        return None;
    }
    let rest = &content[n..];
    if !rest.starts_with(' ') {
        return None;
    }
    let text = rest.trim_start().to_string();
    Some((n, text))
}

fn is_rule(content: &str) -> bool {
    let t = content.trim();
    if t.len() < 3 {
        return false;
    }
    let c = t.chars().next().unwrap();
    if c != '-' && c != '*' && c != '_' {
        return false;
    }
    if !t.chars().all(|x| x == c || x == ' ') {
        return false;
    }
    t.chars().filter(|&x| x == c).count() >= 3
}

fn is_separator(content: &str) -> bool {
    let t = content.trim();
    if t.is_empty() || !t.starts_with('|') {
        return false;
    }
    t.chars().all(|c| matches!(c, '|' | '-' | ':' | ' '))
}

fn parse_row(line: &str) -> Vec<Vec<Inline>> {
    let mut cells = Vec::new();
    let t = line.trim();
    let t = t.strip_prefix('|').unwrap_or(t);
    let t = t.strip_suffix('|').unwrap_or(t);
    for cell in t.split('|') {
        cells.push(Vec::new());
        let _ = cell;
    }
    cells
}

#[derive(Clone, Debug)]
struct Marker {
    ordered: bool,
    number: usize,
    len: usize,
}

fn list_marker(content: &str) -> Option<Marker> {
    let chars: Vec<char> = content.chars().collect();
    if chars.is_empty() {
        return None;
    }
    let c = chars[0];
    if c == '-' || c == '*' || c == '+' {
        if chars.len() == 1 {
            return Some(Marker {
                ordered: false,
                number: 0,
                len: 1,
            });
        }
        if chars[1] == ' ' {
            return Some(Marker {
                ordered: false,
                number: 0,
                len: 2,
            });
        }
        return None;
    }
    if c.is_ascii_digit() {
        let mut n = 0;
        while chars.get(n).map(|c| c.is_ascii_digit()).unwrap_or(false) {
            n += 1;
        }
        let delim = chars.get(n).copied();
        let after = chars.get(n + 1).copied();
        if let Some(d) = delim {
            if (d == '.' || d == ')') && (after == Some(' ') || after.is_none()) {
                let number: String = chars[..n].iter().collect();
                return Some(Marker {
                    ordered: true,
                    number: number.parse().unwrap_or(1),
                    len: n + 1 + if after == Some(' ') { 1 } else { 0 },
                });
            }
        }
    }
    None
}

fn note_def_label(content: &str) -> Option<String> {
    if !content.starts_with("[^") {
        return None;
    }
    let end = content.find("]:")?;
    let label = content[2..end].to_string();
    if label.is_empty() {
        return None;
    }
    Some(label)
}

fn note_def_text(content: &str) -> &str {
    let end = content.find("]:").unwrap();
    let rest = &content[end + 2..];
    rest.trim_start()
}

fn link_def(content: &str) -> Option<(String, String, Option<String>)> {
    if !content.starts_with('[') {
        return None;
    }
    let end = content.find("]:")?;
    let label = content[1..end].to_string();
    if label.is_empty() || label.starts_with('^') {
        return None;
    }
    let rest = content[end + 2..].trim();
    if rest.is_empty() {
        return None;
    }
    let (url, title) = split_url_title(rest);
    Some((label, url, title))
}

fn split_url_title(rest: &str) -> (String, Option<String>) {
    if rest.starts_with('<') {
        if let Some(end) = rest.find('>') {
            let url = rest[1..end].to_string();
            let rest = rest[end + 1..].trim_start();
            let title = if rest.starts_with('"') || rest.starts_with('\'') {
                let q = rest.chars().next().unwrap();
                Some(rest[1..].trim_end_matches(q).to_string())
            } else {
                None
            };
            return (url, title);
        }
    }
    match rest.find(' ') {
        None => (rest.to_string(), None),
        Some(pos) => {
            let url = rest[..pos].to_string();
            let rest = rest[pos..].trim_start();
            let title = if rest.starts_with('"') || rest.starts_with('\'') {
                let q = rest.chars().next().unwrap();
                let inner = &rest[1..];
                match inner.rfind(q) {
                    Some(e) => Some(inner[..e].to_string()),
                    None => Some(inner.to_string()),
                }
            } else {
                None
            };
            (url, title)
        }
    }
}

fn note_ref(chars: &[char], i: usize) -> Option<(String, usize)> {
    if chars.get(i + 1) != Some(&'^') {
        return None;
    }
    let mut j = i + 2;
    while j < chars.len() && chars[j] != ']' {
        if chars[j].is_whitespace() {
            return None;
        }
        j += 1;
    }
    if j >= chars.len() {
        return None;
    }
    let label: String = chars[i + 2..j].iter().collect();
    if label.is_empty() {
        return None;
    }
    Some((label, j + 1))
}

fn autolink(chars: &[char], i: usize) -> Option<(String, usize)> {
    let mut j = i + 1;
    while j < chars.len() && chars[j] != '>' {
        if chars[j].is_whitespace() || chars[j] == '<' {
            return None;
        }
        j += 1;
    }
    if j >= chars.len() {
        return None;
    }
    let url: String = chars[i + 1..j].iter().collect();
    if !url.contains("://") {
        return None;
    }
    Some((url, j + 1))
}

fn entity(chars: &[char], i: usize) -> Option<(String, usize)> {
    let mut j = i + 1;
    while j < chars.len() && chars[j] != ';' && j - i < 12 {
        j += 1;
    }
    if j >= chars.len() || chars[j] != ';' {
        return None;
    }
    let name: String = chars[i + 1..j].iter().collect();
    if name.is_empty() {
        return None;
    }
    if let Some(num) = name.strip_prefix('#') {
        let code = if let Some(hex) = num.strip_prefix('x').or_else(|| num.strip_prefix('X')) {
            u32::from_str_radix(hex, 16).ok()?
        } else {
            num.parse::<u32>().ok()?
        };
        return Some((char::from_u32(code)?.to_string(), j - i + 1));
    }
    let decoded = match name.as_str() {
        "amp" => "&",
        "lt" => "<",
        "gt" => ">",
        "quot" => "\"",
        "apos" => "'",
        "nbsp" => "\u{a0}",
        "hellip" => "\u{2026}",
        "ndash" => "\u{2013}",
        "mdash" => "\u{2014}",
        "laquo" => "«",
        "raquo" => "»",
        "copy" => "©",
        "reg" => "®",
        "trade" => "™",
        _ => return None,
    };
    Some((decoded.to_string(), j - i + 1))
}

fn try_link(chars: &[char], i: usize, _sup: bool) -> Option<usize> {
    let _ = chars;
    let _ = i;
    Some(0)
}

fn inline_link(
    chars: &[char],
    i: usize,
    _sup: bool,
) -> (Inline, usize) {
    // find the matching ']'
    let mut j = i + 1;
    let mut depth = 0;
    while j < chars.len() {
        match chars[j] {
            '[' => depth += 1,
            ']' => {
                if depth == 0 {
                    break;
                }
                depth -= 1;
            }
            _ => {}
        }
        j += 1;
    }
    let text: String = chars[i + 1..j.min(chars.len())].iter().collect();
    let mut k = j + 1;
    let mut url = String::new();
    let mut title = None;
    let mut reference = false;
    if chars.get(k) == Some(&'(') {
        // inline link
        let mut depth = 1;
        let mut e = k + 1;
        while e < chars.len() {
            match chars[e] {
                '(' => depth += 1,
                ')' => {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
                _ => {}
            }
            e += 1;
        }
        let inner: String = chars[k + 1..e.min(chars.len())].iter().collect();
        let (u, t) = split_url_title(inner.trim());
        url = u;
        title = t;
        k = e + 1;
    } else if chars.get(k) == Some(&'[') {
        reference = true;
        let mut e = k + 1;
        while e < chars.len() && chars[e] != ']' {
            e += 1;
        }
        let label: String = chars[k + 1..e.min(chars.len())].iter().collect();
        url = if label.is_empty() { text.clone() } else { label };
        k = e + 1;
    } else {
        url = text.clone();
        k = j + 1;
    }
    let text_inlines = parse_inline_text(&text, false, &Parser::new("", &Config::new("en")));
    let _ = reference;
    (
        Inline::Link {
            url,
            title,
            text: text_inlines,
        },
        k,
    )
}

fn try_image(chars: &[char], i: usize) -> Option<(Inline, usize)> {
    let mut j = i + 2;
    while j < chars.len() && chars[j] != ']' {
        j += 1;
    }
    if j >= chars.len() {
        return None;
    }
    let alt: String = chars[i + 2..j].iter().collect();
    let mut k = j + 1;
    if chars.get(k) != Some(&'(') {
        return None;
    }
    let mut depth = 1;
    let mut e = k + 1;
    while e < chars.len() {
        match chars[e] {
            '(' => depth += 1,
            ')' => {
                depth -= 1;
                if depth == 0 {
                    break;
                }
            }
            _ => {}
        }
        e += 1;
    }
    if e >= chars.len() {
        return None;
    }
    let inner: String = chars[k + 1..e].iter().collect();
    let (url, title) = split_url_title(inner.trim());
    Some((
        Inline::Image {
            url,
            title,
            alt,
        },
        e + 1,
    ))
}

// ---- typographic cleaning ---------------------------------------------------

pub fn clean(text: &str, config: &Config) -> String {
    if !config.get_bool("input.clean", true) {
        return text.to_string();
    }
    let lang = config.get_str_or("lang", "en");
    let mut out = text.to_string();
    if config.get_bool("input.clean.smart_quotes", true) {
        out = smart_quotes(&out);
    }
    if config.get_bool("input.clean.ligature.dashes", false) {
        out = out.replace("---", "—").replace("--", "–");
    }
    if config.get_bool("input.clean.ligature.guillemets", false) {
        out = out.replace("<<", "«").replace(">>", "»");
    }
    if lang == "fr" {
        out = out.replace("...", "…");
        out = french_nb_spaces(&out);
    }
    out
}

fn smart_quotes(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    let mut in_double = false;
    let mut in_single = false;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '"' => {
                let prev = if i == 0 { None } else { Some(chars[i - 1]) };
                let opening = match prev {
                    None => true,
                    Some(p) => p.is_whitespace() || "([{".contains(p),
                };
                if opening {
                    out.push('“');
                    in_double = true;
                } else {
                    out.push('”');
                    in_double = false;
                }
            }
            '\'' => {
                let prev = if i == 0 { None } else { Some(chars[i - 1]) };
                let next = chars.get(i + 1).copied();
                let opening = match prev {
                    None => true,
                    Some(p) => p.is_whitespace() || "([{".contains(p),
                };
                if opening && next.map(|n| !n.is_whitespace()).unwrap_or(false) {
                    out.push('‘');
                    in_single = true;
                } else if !in_single {
                    out.push('’');
                } else {
                    out.push('’');
                    in_single = false;
                }
            }
            _ => out.push(c),
        }
        i += 1;
    }
    out
}

/// French narrow no-break spaces.
fn french_nb_spaces(text: &str) -> String {
    let chars: Vec<char> = text.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == ' ' {
            let prev = if i == 0 { None } else { Some(chars[i - 1]) };
            let next = chars.get(i + 1).copied();
            // rule: space before ; ! ?
            if matches!(next, Some(';') | Some('!') | Some('?')) {
                out.push('\u{a0}');
                i += 1;
                continue;
            }
            // rule: space after a digit
            if prev.map(|p| p.is_ascii_digit()).unwrap_or(false) {
                // the following token
                let mut j = i + 1;
                while j < chars.len() && !chars[j].is_whitespace() {
                    j += 1;
                }
                let token: String = chars[i + 1..j].iter().collect();
                let follower = chars.get(j).copied();
                let len = token.chars().count();
                let digit_start = token.chars().next().map(|c| c.is_ascii_digit()).unwrap_or(false);
                let two_letters = len == 2
                    && token.chars().all(|c| c.is_alphabetic());
                let three = len == 3
                    && follower
                        .map(|f| f.is_whitespace())
                        .unwrap_or(false);
                if digit_start || two_letters || three {
                    out.push('\u{a0}');
                    i += 1;
                    continue;
                }
            }
            out.push(' ');
            i += 1;
            continue;
        }
        out.push(c);
        i += 1;
    }
    out
}

