    if let Some(pos) = cond.find('|') {
        let name = cond[..pos].trim();
        let rest = cond[pos + 1..].trim();
        if let Some(value) = rest.strip_prefix("eq:") {
            let value = value.trim().trim_matches('"');
            return vars.get(name).map(|s| s.as_str()) == Some(value);
        }
    }
    match cond {
        "true" => true,
        _ => vars.contains_key(cond),
    }
