//! Rendering to HTML (single file) and XHTML (EPUB chapters).

use super::template::render;
use crate::config::Config;
use crate::localization::Localization;
use crate::parser::{Block, Doc, Inline};
use std::collections::HashMap;
use std::path::Path;

/// HTML-escapes a string (for text content).
pub fn escape(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            _ => out.push(c),
        }
    }
    out
}

/// HTML-escapes a string for an attribute.
pub fn escape_attr(s: &str) -> String {
    let mut out = String::new();
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            _ => out.push(c),
        }
    }
    out
}

/// Replaces non-breaking spaces with HTML entities.
fn escape_nb(s: &str) -> String {
    s.replace('\u{a0}', "&#160;").replace('\u{202f}', "&#8239;")
}

/// State used while rendering a document.
pub struct Renderer<'a> {
    pub config: &'a Config,
    pub l10n: Localization,
    /// Counters for the `id` attributes.
    pub link: usize,
    pub para: usize,
    /// Path of the chapter file, for resolving images and links.
    pub source: String,
    /// Whether footnotes are displayed as side notes.
    pub side_notes: bool,
    /// XHTML (EPUB) rendering instead of HTML.
    pub xhtml: bool,
    /// Notes collected while rendering the chapter.
    pub notes: Vec<(String, Vec<Block>)>,
    /// Base path for images.
    pub image_base: String,
    /// Counter for the images copied to the EPUB.
    pub images: &'a mut Vec<String>,
    /// Counter for the footnotes of the current chapter.
    pub note_counter: usize,
    /// Prefix used for the note ids.
    pub note_prefix: String,
}

impl<'a> Renderer<'a> {
    pub fn new(
        config: &'a Config,
        source: &str,
        images: &'a mut Vec<String>,
        xhtml: bool,
        note_prefix: String,
    ) -> Renderer<'a> {
        Renderer {
            config,
            l10n: Localization::new(&config.get_str_or("lang", "en")),
            link: 0,
            para: 0,
            source: source.to_string(),
            side_notes: config.get_bool("html.side_notes", false),
            xhtml,
            notes: Vec::new(),
            image_base: String::new(),
            images,
            note_counter: 0,
            note_prefix,
        }
    }

    // ---- blocks --------------------------------------------------------------

    pub fn render_blocks(&mut self, blocks: &[Block]) -> String {
        let mut out = String::new();
        for block in blocks {
            out.push_str(&self.render_block(block));
        }
        out
    }

    pub fn render_block(&mut self, block: &Block) -> String {
        match block {
            Block::Heading { level, inline } => {
                let link = self.link;
                self.link += 1;
                let text = self.render_inlines(inline);
                if level == 1 && self.is_chapter_heading {
                    // handled elsewhere
                }
                format!("<h{level} id = \"link-{link}\">{text}</h{level}>\n")
            }
            Block::Paragraph(inline) => {
                let n = self.para;
                self.para += 1;
                let text = self.render_inlines(inline);
                format!("<p id = \"para-{n}\">{text}</p>\n")
            }
            Block::Quote(blocks) => {
                let inner = self.render_blocks(blocks);
                format!("<blockquote>{inner}</blockquote>\n")
            }
            Block::Bullet(items) => {
                let mut out = String::from("<ul>\n");
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("<li>{inner}</li>\n"));
                }
                out.push_str("</ul>\n");
                out
            }
            Block::Ordered { start, items } => {
                let mut out = if *start == 1 {
                    String::from("<ol>\n")
                } else {
                    format!("<ol start = \"{}\">\n", start)
                };
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("<li>{inner}</li>\n"));
                }
                out.push_str("</ol>\n");
                out
            }
            Block::DefList(entries) => {
                let mut out = String::from("<dl>\n");
                for (term, blocks) in entries {
                    let t = self.render_inlines(term);
                    out.push_str(&format!("<dt>{t}</dt>\n"));
                    let b = self.render_blocks(blocks);
                    out.push_str(&format!("<dd>{b}</dd>\n"));
                }
                out.push_str("</dl>\n");
                out
            }
            Block::Code { lang, text, .. } => {
                let highlighted = crate::render::highlight::highlight(
                    text,
                    lang.as_deref(),
                    self.config,
                    "InspiredGitHub",
                );
                let mut out = String::from("<pre>");
                for line in highlighted.lines() {
                    if line.is_empty() {
                        out.push('\n');
                    } else {
                        out.push_str(&line);
                        out.push('\n');
                    }
                }
                out.push('\n');
                out.push_str("</pre>\n");
                out
            }
            Block::Table { head, rows } => {
                let mut out = String::from("<div class = \"table\">\n    <table>\n");
                out.push_str("<tr>\n");
                for cell in head {
                    let c = self.render_inlines(cell);
                    out.push_str(&format!("<th>{c}</th>"));
                }
                out.push_str("</tr>\n");
                for row in rows {
                    out.push_str("<tr>\n");
                    for cell in row {
                        let c = self.render_inlines(cell);
                        out.push_str(&format!("<td>{c}</td>"));
                    }
                    out.push_str("</tr>\n");
                }
                out.push('\n');
                out.push_str("    </table>\n</div>\n");
                out
            }
            Block::Rule => format!("<p class = \"rule\">***</p>\n"),
            Block::NoteDef { .. } => String::new(),
            Block::LinkDef { .. } => String::new(),
            Block::Yaml(_) => String::new(),
        }
    }

    // ---- inline --------------------------------------------------------------

    pub fn render_inlines(&mut self, inlines: &[Inline]) -> String {
        let mut out = String::new();
        for inline in inlines {
            out.push_str(&self.render_inline(inline));
        }
        out
    }

    pub fn render_inline(&mut self, inline: &Inline) -> String {
        match inline {
            Inline::Text(t) => {
                let mut t = escape(t);
                if self.config.get_bool("html.escape_nb_spaces", true)
                    || self.config.get_bool("epub.escape_nb_spaces", true)
                {
                    t = escape_nb(&t);
                }
                t
            }
            Inline::Em(i) => format!("<em>{}</em>", self.render_inlines(i)),
            Inline::Strong(i) => format!("<b>{}</b>", self.render_inlines(i)),
            Inline::Del(i) => format!("<del>{}</del>", self.render_inlines(i)),
            Inline::Code(c) => format!("<code>{}</code>", escape(c)),
            Inline::SoftBreak => " ".to_string(),
            Inline::HardBreak => "<br />\n".to_string(),
            Inline::Note(label) => {
                let n = self.note_counter + 1;
                self.note_counter += 1;
                format!(
                    "<a class = \"footnote_reference\" href = \"#note-dest-{}\" id = \"note-source-{}\"><sup>[{}]</sup></a>",
                    format!("{}-{}", self.note_prefix, n),
                    format!("{}-{}", self.note_prefix, n),
                    label
                )
            }
            Inline::Sup(i) => format!("<sup>{}</sup>", self.render_inlines(i)),
            Inline::Sub(i) => format!("<sub>{}</sub>", self.render_inlines(i)),
            Inline::Link { url, title, text } => {
                let href = self.resolve_link(url);
                let title_attr = match title {
                    Some(t) => format!(" title = \"{}\"", escape_attr(t)),
                    None => String::new(),
                };
                format!(
                    "<a href = \"{}\"{}>{}</a>",
                    escape_attr(&href),
                    title_attr,
                    self.render_inlines(text)
                )
            }
            Inline::Image { url, title, alt } => {
                let src = self.resolve_image(url);
                format!(
                    "<img src = \"{}\" title = \"{}\" alt = \"{}\" />",
                    escape_attr(&src),
                    escape_attr(title.as_deref().unwrap_or("")),
                    escape_attr(alt)
                )
            }
        }
    }

    fn resolve_link(&mut self, url: &str) -> String {
        url.to_string()
    }

    fn resolve_image(&mut self, url: &str) -> String {
        url.to_string()
    }
}

pub fn is_chapter_heading() -> bool {
    false
}

/// Adds a field to the `is_chapter_heading` hack.
pub trait ChapterHeading {
    fn is_chapter_heading(&self) -> bool;
}
RSEOF
echo ok"}

