                ));
            } else {
                out.push_str(&format!(
                    "  <aside class = \"footnote\" id = \"note-dest-{id}\">{inner}</aside>\n"
                ));
            }
            out.push_str("  </td>\n");
            out.push_str("</tr>\n");
        }
        out.push_str("</table>\n");
        if self.xhtml {
