        }
        out
    }

    pub fn render_inline(&mut self, inline: &Inline) -> String {
        match inline {
            Inline::Text(t) => {
                let mut t = escape(t);
                if self.config.get_bool("html.escape_nb_spaces", true) {
                    t = escape_nb(&t);
                }
                t
            }
            Inline::Em(i) => format!("<em>{}</em>", self.render_inlines(i)),
            Inline::Strong(i) => format!("<b>{}</b>", self.render_inlines(i)),
            Inline::Del(i) => format!("<del>{}</del>", self.render_inlines(i)),
            Inline::Code(c) => format!("<code>{}</code>", escape(c)),
            Inline::SoftBreak => " ".to_string(),
            Inline::HardBreak => "<br />\n".to_string(),
            Inline::Note(label) => {
                let n = self.note_counter + 1;
                self.note_counter += 1;
                let id = format!("{}-{}", self.note_prefix, n);
                if self.xhtml {
                    format!(
                        "<a  href = \"#note-dest-{id}\"><sup id = \"note-source-{id}\">[{label}]</sup></a>"
                    )
                } else {
                    format!(
                        "<a class = \"footnote_reference\" href = \"#note-dest-{id}\" id = \"note-source-{id}\"><sup>[{label}]</sup></a>"
                    )
                }
            }
            Inline::Sup(i) => format!("<sup>{}</sup>", self.render_inlines(i)),
            Inline::Sub(i) => format!("<sub>{}</sub>", self.render_inlines(i)),
            Inline::Link { url, title, text } => {
                let href = self.resolve_link(url);
                let title_attr = match title {
                    Some(t) => format!(" title = \"{}\"", escape_attr(t)),
                    None => String::new(),
                };
                format!(
                    "<a href = \"{}\"{}>{}</a>",
                    escape_attr(&href),
                    title_attr,
                    self.render_inlines(text)
                )
            }
            Inline::Image { url, title, alt } => {
                let src = self.resolve_image(url);
                format!(
                    "<img src = \"{}\" title = \"{}\" alt = \"{}\" />",
                    escape_attr(&src),
                    escape_attr(title.as_deref().unwrap_or("")),
                    escape_attr(alt)
                )
            }
        }
    }

    pub fn resolve_link(&self, url: &str) -> String {
        url.to_string()
    }

    pub fn resolve_image(&mut self, url: &str) -> String {
        url.to_string()
    }

    /// Renders a chapter heading with the inline template.
    pub fn chapter_heading(
        &mut self,
        template: &str,
        header: Option<&str>,
        number: Option<usize>,
        title: &str,
    ) -> String {
        let link = self.link;
        self.link += 1;
        let mut vars: HashMap<&str, String> = HashMap::new();
        vars.insert("link", link.to_string());
        vars.insert("header", header.unwrap_or("").to_string());
        vars.insert("number", number.map(|n| n.to_string()).unwrap_or_default());
        vars.insert("title", title.to_string());
        if let Some(header) = header {
            vars.insert("has_number", "1".to_string());
        }
        if !title.is_empty() {
            vars.insert("has_title", "1".to_string());
        }
        render(template, &vars)
    }
}
RSEOF
echo ok"}

