                let text = self.render_inlines(inline);
                format!("<p id = \"para-{n}\">{text}</p>\n")
            }
            Block::Quote(blocks) => {
                let inner = self.render_blocks(blocks);
                format!("<blockquote>{inner}</blockquote>\n")
            }
            Block::Bullet(items) => {
                let mut out = String::from("<ul>\n");
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("<li>{inner}</li>\n"));
                }
                out.push_str("</ul>\n");
                out
            }
            Block::Ordered { start, items } => {
                let mut out = if *start == 1 {
                    String::from("<ol>\n")
                } else {
                    format!("<ol start = \"{}\">\n", start)
                };
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("<li>{inner}</li>\n"));
                }
                out.push_str("</ol>\n");
                out
            }
            Block::DefList(entries) => {
                let mut out = String::from("<dl>\n");
                for (term, blocks) in entries {
                    let t = self.render_inlines(term);
                    out.push_str(&format!("<dt>{t}</dt>\n"));
                    let b = self.render_blocks(blocks);
                    out.push_str(&format!("<dd>{b}</dd>\n"));
                }
                out.push_str("</dl>\n");
                out
            }
            Block::Code { lang, text, .. } => {
                let highlighted = crate::render::highlight::highlight(
                    text,
                    lang.as_deref(),
                    self.config,
                    "InspiredGitHub",
                );
                let mut out = String::from("<pre>");
                for line in highlighted.lines() {
                    if line.is_empty() {
                        out.push('\n');
                    } else {
                        out.push_str(&line);
                        out.push('\n');
                    }
                }
                out.push('\n');
                out.push_str("</pre>\n");
                out
            }
            Block::Table { head, rows } => {
                let mut out = String::from("<div class = \"table\">\n    <table>\n<tr>\n");
                for cell in head {
                    let c = self.render_inlines(cell);
                    out.push_str(&format!("<th>{c}</th>"));
                }
                out.push_str("</tr>\n");
                for row in rows {
                    out.push_str("<tr>\n");
                    for cell in row {
                        let c = self.render_inlines(cell);
                        out.push_str(&format!("<td>{c}</td>"));
                    }
                    out.push_str("</tr>\n");
                }
                out.push('\n');
                out.push_str("    </table>\n</div>\n");
                out
            }
            Block::Rule => "<p class = \"rule\">***</p>\n".to_string(),
            Block::NoteDef { .. } => String::new(),
            Block::LinkDef { .. } => String::new(),
            Block::Yaml(_) => String::new(),
        }
    }

    /// Renders the notes at the end of a chapter.
    pub fn render_notes(&mut self) -> String {
        if self.notes.is_empty() {
            return String::new();
        }
        let mut out = String::new();
        if self.xhtml {
            out.push_str("<div class = \"notes\" >\n");
        } else {
            out.push_str("<section class = \"notes\" >\n");
        }
        out.push_str(&format!(
            " <h2 class = \"notes\">{}</h2>\n",
            self.l10n.get("notes")
        ));
        out.push_str("<table class = \"notes\">\n");
        let notes = self.notes.clone();
        for (i, (label, blocks)) in notes.iter().enumerate() {
            let n = i + 1;
            let id = format!("{}-{}", self.note_prefix, n);
            out.push_str("<tr class = \"notes\">\n");
            out.push_str(" <td class = \"note-number\">\n");
            out.push_str("  <p class = \"note-number\">\n");
            if self.xhtml {
                out.push_str(&format!(
                    "  <a href = \"#note-source-{id}\">[{label}]</a>\n"
                ));
            } else {
                out.push_str(&format!(
                    "  <a rel = \"footnote\" href = \"#note-source-{id}\">[{label}]</a>\n"
                ));
            }
            out.push_str("</p>\n");
            out.push('\n');
            out.push_str(" </td>\n");
            out.push_str(" <td class = \"note\">\n");
            let inner = self.render_blocks(blocks);
            if self.xhtml {
                out.push_str(&format!(
                    "  <a id = \"note-dest-{id}\" />{inner}\n"
                ));
            } else {
                out.push_str(&format!(
                    "  <aside class = \"footnote\" id = \"note-dest-{id}\">{inner}</aside>\n"
                ));
            }
            out.push_str("  </td>\n");
            out.push_str("</tr>\n");
        }
        out.push_str("</table>\n");
        if self.xhtml {
            out.push_str("</div>\n\n");
        } else {
            out.push_str("</section>\n\n");
        }
        out
    }

    // ---- inline --------------------------------------------------------------

    pub fn render_inlines(&mut self, inlines: &[Inline]) -> String {
        let mut out = String::new();
        for inline in inlines {
            out.push_str(&self.render_inline(inline));
        }
        out
    }

    pub fn render_inline(&mut self, inline: &Inline) -> String {
        match inline {
            Inline::Text(t) => {
                let mut t = escape(t);
                if self.config.get_bool("html.escape_nb_spaces", true) {
                    t = escape_nb(&t);
                }
                t
            }
            Inline::Em(i) => format!("<em>{}</em>", self.render_inlines(i)),
            Inline::Strong(i) => format!("<b>{}</b>", self.render_inlines(i)),
            Inline::Del(i) => format!("<del>{}</del>", self.render_inlines(i)),
            Inline::Code(c) => format!("<code>{}</code>", escape(c)),
            Inline::SoftBreak => " ".to_string(),
            Inline::HardBreak => "<br />\n".to_string(),
            Inline::Note(label) => {
                let n = self.note_counter + 1;
                self.note_counter += 1;
                let id = format!("{}-{}", self.note_prefix, n);
                if self.xhtml {
                    format!(
                        "<a  href = \"#note-dest-{id}\"><sup id = \"note-source-{id}\">[{label}]</sup></a>"
                    )
                } else {
                    format!(
                        "<a class = \"footnote_reference\" href = \"#note-dest-{id}\" id = \"note-source-{id}\"><sup>[{label}]</sup></a>"
                    )
                }
            }
            Inline::Sup(i) => format!("<sup>{}</sup>", self.render_inlines(i)),
            Inline::Sub(i) => format!("<sub>{}</sub>", self.render_inlines(i)),
            Inline::Link { url, title, text } => {
                let href = self.resolve_link(url);
                let title_attr = match title {
                    Some(t) => format!(" title = \"{}\"", escape_attr(t)),
                    None => String::new(),
                };
                format!(
                    "<a href = \"{}\"{}>{}</a>",
                    escape_attr(&href),
                    title_attr,
                    self.render_inlines(text)
                )
            }
            Inline::Image { url, title, alt } => {
                let src = self.resolve_image(url);
                format!(
                    "<img src = \"{}\" title = \"{}\" alt = \"{}\" />",
                    escape_attr(&src),
                    escape_attr(title.as_deref().unwrap_or("")),
                    escape_attr(alt)
                )
            }
        }
    }

    pub fn resolve_link(&self, url: &str) -> String {
        url.to_string()
    }

    pub fn resolve_image(&mut self, url: &str) -> String {
        url.to_string()
    }

    /// Renders a chapter heading with the inline template.
    pub fn chapter_heading(
        &mut self,
        template: &str,
        header: Option<&str>,
        number: Option<usize>,
        title: &str,
    ) -> String {
        let link = self.link;
        self.link += 1;
        let mut vars: HashMap<&str, String> = HashMap::new();
        vars.insert("link", link.to_string());
        vars.insert("header", header.unwrap_or("").to_string());
        vars.insert("number", number.map(|n| n.to_string()).unwrap_or_default());
        vars.insert("title", title.to_string());
        if let Some(header) = header {
            vars.insert("has_number", "1".to_string());
        }
        if !title.is_empty() {
            vars.insert("has_title", "1".to_string());
        }
        render(template, &vars)
    }
}
RSEOF
echo ok"}

