//! Syntax highlighting, mimicking the output of syntect with the
//! InspiredGitHub theme.

use crate::config::Config;

#[derive(Clone, Copy, PartialEq)]
enum Style {
    Text,
    Keyword,
    Function,
    Number,
    String,
    Comment,
}

impl Style {
    fn css(&self) -> &'static str {
        match self {
            Style::Text => "color:#323232;",
            Style::Keyword => "font-weight:bold;color:#a71d5d;",
            Style::Function => "font-weight:bold;color:#795da3;",
            Style::Number => "color:#0086b3;",
            Style::String => "color:#183691;",
            Style::Comment => "color:#969896;",
        }
    }
}

struct Token {
    style: Style,
    text: String,
}

/// Highlights `text` (which ends with a newline) with the given language.
pub fn highlight(text: &str, lang: Option<&str>, config: &Config, _theme: &str) -> String {
    if config.get_str_or("rendering.highlight", "syntect") == "none" {
        return escape_lines(text);
    }
    let mut out = String::new();
    for line in text.split('\n') {
        if line.is_empty() {
            out.push('\n');
            continue;
        }
        let tokens = tokenize(line, lang);
        let mut spans = String::new();
        let mut current: Option<Style> = None;
        let mut buf = String::new();
        for token in tokens {
            if current != Some(token.style) {
                if !buf.is_empty() {
                    let style = current.unwrap_or(Style::Text);
                    spans.push_str(&format!(
                        "<span style=\"{}\">{}</span>",
                        style.css(),
                        crate::render::html::escape(&buf)
                    ));
                    buf.clear();
                }
                current = Some(token.style);
            }
            buf.push_str(&token.text);
        }
        if !buf.is_empty() {
            let style = current.unwrap_or(Style::Text);
            spans.push_str(&format!(
                "<span style=\"{}\">{}</span>",
                style.css(),
                crate::render::html::escape(&buf)
            ));
        }
        out.push_str(&spans);
        out.push('\n');
    }
    out
}

fn escape_lines(text: &str) -> String {
    let mut out = String::new();
    for line in text.split('\n') {
        if line.is_empty() {
            out.push('\n');
        } else {
            out.push_str(&format!(
                "<span style=\"color:#323232;\">{}</span>\n",
                crate::render::html::escape(line)
            ));
        }
    }
    out
}

fn tokenize(line: &str, lang: Option<&str>) -> Vec<Token> {
    let lang = lang.unwrap_or("");
    let keywords: &[&str] = match lang {
        "rust" => &[
            "as", "async", "await", "break", "const", "continue", "crate", "dyn", "else", "enum",
            "extern", "false", "fn", "for", "if", "impl", "in", "let", "loop", "match", "mod",
            "move", "mut", "pub", "ref", "return", "self", "Self", "static", "struct", "super",
            "trait", "true", "type", "unsafe", "use", "where", "while", "yield",
        ],
        "c" | "cpp" | "h" => &[
            "auto", "break", "case", "char", "const", "continue", "default", "do", "double",
            "else", "enum", "extern", "float", "for", "goto", "if", "int", "long", "register",
            "return", "short", "signed", "sizeof", "static", "struct", "switch", "typedef",
            "union", "unsigned", "void", "volatile", "while",
        ],
        "python" | "py" => &[
            "and", "as", "assert", "async", "await", "break", "class", "continue", "def", "del",
            "elif", "else", "except", "finally", "for", "from", "global", "if", "import", "in",
            "is", "lambda", "nonlocal", "not", "or", "pass", "raise", "return", "try", "while",
            "with", "yield", "True", "False", "None",
        ],
        "js" | "javascript" => &[
            "break", "case", "catch", "class", "const", "continue", "debugger", "default",
            "delete", "do", "else", "export", "extends", "finally", "for", "function", "if",
            "import", "in", "instanceof", "let", "new", "return", "super", "switch", "this",
            "throw", "try", "typeof", "var", "void", "while", "with", "yield",
        ],
        _ => &[],
    };
    let comment_start: Option<&str> = match lang {
        "python" | "py" | "sh" | "bash" | "yaml" | "yml" | "toml" | "ini" | "ruby" | "r" => Some("#"),
        "sql" => Some("--"),
        _ => Some("//"),
    };
    let mut tokens: Vec<Token> = Vec::new();
    let chars: Vec<char> = line.chars().collect();
    let mut i = 0;
    let mut buf = String::new();
    let mut push = |style: Style, text: &str, tokens: &mut Vec<Token>| {
        tokens.push(Token {
            style,
            text: text.to_string(),
        });
    };
    while i < chars.len() {
        let c = chars[i];
        // comment
        if let Some(cs) = comment_start {
            let cs_chars: Vec<char> = cs.chars().collect();
            if chars[i..].starts_with(&cs_chars) {
                if !buf.is_empty() {
                    push(Style::Text, &buf, &mut tokens);
                    buf.clear();
                }
                let rest: String = chars[i..].iter().collect();
                push(Style::Comment, &rest, &mut tokens);
                break;
            }
        }
        if c.is_alphabetic() || c == '_' {
            let start = i;
            while i < chars.len() && (chars[i].is_alphanumeric() || chars[i] == '_') {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            if !buf.is_empty() {
                push(Style::Text, &buf, &mut tokens);
                buf.clear();
            }
            if keywords.contains(&word.as_str()) {
                push(Style::Keyword, &word, &mut tokens);
            } else if chars.get(i) == Some(&'(') {
                push(Style::Function, &word, &mut tokens);
            } else {
                push(Style::Text, &word, &mut tokens);
            }
            continue;
        }
        if c.is_ascii_digit() {
            let start = i;
            while i < chars.len()
                && (chars[i].is_ascii_digit()
                    || chars[i] == '.'
                    || chars[i] == '_'
                    || chars[i] == 'x'
                    || chars[i].is_ascii_hexdigit())
            {
                i += 1;
            }
            if !buf.is_empty() {
                push(Style::Text, &buf, &mut tokens);
                buf.clear();
            }
            let num: String = chars[start..i].iter().collect();
            push(Style::Number, &num, &mut tokens);
            continue;
        }
        if c == '"' || c == '\'' || c == '`' {
            let start = i;
            i += 1;
            while i < chars.len() {
                if chars[i] == '\\' {
                    i += 2;
                    continue;
                }
                if chars[i] == c {
                    i += 1;
                    break;
                }
                i += 1;
            }
            if !buf.is_empty() {
                push(Style::Text, &buf, &mut tokens);
                buf.clear();
            }
            let s: String = chars[start..i.min(chars.len())].iter().collect();
            push(Style::String, &s, &mut tokens);
            continue;
        }
        if matches!(c, '+' | '-' | '=' | '<' | '>' | '!' | '&' | '|' | '%' | '^' | '?' | ':' | '/')
        {
            if !buf.is_empty() {
                push(Style::Text, &buf, &mut tokens);
                buf.clear();
            }
            let start = i;
            while i < chars.len() && chars[i] == c {
                i += 1;
            }
            let op: String = chars[start..i].iter().collect();
            push(Style::Keyword, &op, &mut tokens);
            continue;
        }
        buf.push(c);
        i += 1;
    }
    if !buf.is_empty() {
        push(Style::Text, &buf, &mut tokens);
    }
    tokens
}
