//! The book: configuration, chapters and rendering.

use crate::config::{Config, CrowbookError, Res, Source};
use crate::parser::{Block, Doc, Parser};
use crate::render::html::{escape, escape_attr};
use std::collections::HashMap;
use std::path::Path;

/// One element of the book: either a part or a chapter file.
pub enum Entry {
    Part {
        title: String,
        number: usize,
    },
    Chapter {
        /// Name of the Markdown file, used for the statistics.
        name: String,
        /// Whether the chapter is numbered.
        numbered: bool,
        /// Whether the title is taken from the file.
        use_title: bool,
        doc: Doc,
        /// The chapter numbers of the level-1 headings.
        numbers: Vec<usize>,
    },
}

pub struct Book {
    pub config: Config,
    pub entries: Vec<Entry>,
    /// The name of the book configuration file.
    pub file: String,
}

impl Book {
    /// Returns the files of the book, in order.
    pub fn files(&self) -> Vec<String> {
        let mut files = Vec::new();
        for entry in &self.entries {
            if let Entry::Chapter { name, .. } = entry {
                files.push(name.clone());
            }
        }
        files
    }

    /// Number of chapter headings (for the nav).
    pub fn chapter_count(&self) -> usize {
        let mut n = 0;
        for entry in &self.entries {
            match entry {
                Entry::Part { .. } => n += 1,
                Entry::Chapter { doc, .. } => {
                    for block in &doc.blocks {
                        if let Block::Heading { level: 1, .. } = block {
                            n += 1;
                        }
                    }
                }
            }
        }
        n
    }
}

/// Splits a book configuration file into the YAML part and the chapter list.
fn split_book(text: &str) -> (String, Vec<(usize, String)>) {
    let lines: Vec<&str> = text.split('\n').collect();
    let mut chapter_start = lines.len();
    for (i, line) in lines.iter().enumerate() {
        let first = line.chars().next().unwrap_or(' ');
        if matches!(first, '+' | '-' | '!' | '@') {
            chapter_start = i;
            break;
        }
    }
    let yaml = lines[..chapter_start].join("\n");
    let chapters: Vec<(usize, String)> = lines[chapter_start..]
        .iter()
        .enumerate()
        .map(|(i, l)| (chapter_start + i + 1, l.to_string()))
        .collect();
    (yaml, chapters)
}

/// Parses a book configuration file.
pub fn parse_book(
    file: &str,
    config: &mut Config,
    entries: &mut Vec<Entry>,
    errors: &mut Vec<CrowbookError>,
) -> Res<()> {
    let text = match std::fs::read_to_string(file) {
        Ok(t) => t,
        Err(e) => {
            return Err(CrowbookError::fatal(
                Source::none(),
                config.localization().msg(
                    "could_not_find_file",
                    &[
                        ("file", file.to_string()),
                        ("what", "book".to_string()),
                    ],
                ),
            ))
        }
    };
    let (yaml, chapters) = split_book(&text);
    // Parse the options
    let parsed = crate::yaml::parse(&yaml);
    match parsed {
        Err(e) => {
            return Err(CrowbookError::fatal(
                Source::new(file, Some(e.line)),
                format!(
                    "{}YAML block was not valid YAML: {}",
                    config.localization().msg("parse_config_error", &[]),
                    e
                ),
            ))
        }
        Ok(node) => {
            if !matches!(node.value, crate::yaml::Yaml::Hash(_)) {
                let l10n = config.localization();
                let message = format!(
                    "{}\"{}\"\n{}\n",
                    l10n.msg("parse_config_error", &[]),
                    l10n.msg(
                        "could_not_parse_book",
                        &[("file", file.to_string())]
                    ),
                    l10n.msg("maybe_single", &[])
                );
                return Err(CrowbookError::fatal(Source::new(file, None), message));
            }
            if let crate::yaml::Yaml::Hash(pairs) = node.value {
                for (key, value) in pairs {
                    let key = match key {
                        crate::yaml::Yaml::String(s) => s,
                        crate::yaml::Yaml::Null => {
                            errors.push(CrowbookError::error(
                                Source::new(file, None),
                                "Expected a String as a key, found Null".to_string(),
                            ));
                            continue;
                        }
                        other => {
                            errors.push(CrowbookError::error(
                                Source::new(file, None),
                                format!("Expected a String as a key, found {:?}", other),
                            ));
                            continue;
                        }
                    };
                    let line = first_line_of(&yaml, &key);
                    let source = Source::new(file, line);
                    if key == "import" {
                        let path = match &value {
                            crate::yaml::Yaml::String(s) => s.clone(),
                            other => {
                                errors.push(CrowbookError::error(
                                    source,
                                    format!("Expected a string as value for key import, found {:?}", other),
                                ));
                                continue;
                            }
                        };
                        let import_path = if Path::new(&path).is_absolute() {
                            path.clone()
                        } else {
                            let base = Path::new(file).parent().unwrap_or(Path::new(""));
                            base.join(&path).to_string_lossy().to_string()
                        };
                        if let Err(e) = parse_book(&import_path, config, entries, errors) {
                            return Err(e);
                        }
                        continue;
                    }
                    if let Err(e) = config.set(&key, value, &source) {
                        errors.push(e);
                    }
                }
            }
        }
    }
    // Parse the chapters
    let mut part_number = 0;
    for (line_no, line) in chapters {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let first = line.chars().next().unwrap();
        match first {
            '@' => {
                let title = line[1..].trim().to_string();
                part_number += 1;
                entries.push(Entry::Part { title, number: part_number });
            }
            '+' | '-' | '!' => {
                let name = line[1..].trim().to_string();
                let path = if Path::new(&name).is_absolute() {
                    name.clone()
                } else {
                    let base = Path::new(file).parent().unwrap_or(Path::new(""));
                    base.join(&name).to_string_lossy().to_string()
                };
                match std::fs::read_to_string(&path) {
                    Ok(content) => {
                        let doc = Parser::new(&content, config).parse_document();
                        let numbers = Vec::new();
                        entries.push(Entry::Chapter {
                            name,
                            numbered: first == '+',
                            use_title: first != '!',
                            doc,
                            numbers,
                        });
                    }
                    Err(_) => {
                        return Err(CrowbookError::fatal(
                            Source::new(file, Some(line_no)),
                            config.localization().msg(
                                "could_not_find_file",
                                &[
                                    ("file", name.clone()),
                                    ("what", "book chapter".to_string()),
                                ],
                            ),
                        ))
                    }
                }
            }
            _ => {
                return Err(CrowbookError::fatal(
                    Source::new(file, Some(line_no)),
                    "found invalid chapter definition in the chapter list".to_string(),
                ))
            }
        }
    }
    Ok(())
}

/// Finds the line of a key in a YAML text.
fn first_line_of(yaml: &str, key: &str) -> Option<usize> {
    for (i, line) in yaml.split('\n').enumerate() {
        let trimmed = line.trim_start();
        if trimmed.starts_with(key) {
            let rest = &trimmed[key.len()..];
            if rest.starts_with(':') {
                return Some(i + 1);
            }
        }
    }
    None
}
RSEOF
echo ok"}

