pub fn toc(config: &Config, entries: &[Entry]) -> Vec<TocEntry> {
    let l10n = crate::localization::Localization::new(&config.get_str_or("lang", "en"));
    let chapter_name = config.get_str_or("rendering.chapter", &l10n.get("chapter"));
    let part_name = config.get_str_or("rendering.part", &l10n.get("part"));
    let chapter_template = config.get_str_or(
        "rendering.chapter.template",
        "{{number}}. {{chapter_title}}",
    );
    let part_template = config
        .get_str_or("rendering.part.template", "{{number}}. {{part_title}}");
    let roman_chapter = config.get_bool("rendering.chapter.roman_numerals", false);
    let roman_part = config.get_bool("rendering.part.roman_numerals", true);
    let reset = config.get_bool("rendering.part.reset_counter", true);
    let mut chapter_number = 0;
    let mut out = Vec::new();
    let mut link = 1; // link-0 is the title
    let mut stack: Vec<(usize, Vec<TocEntry>)> = Vec::new();
    for entry in entries {
        match entry {
