                let number_str = if roman_part {
                    roman(*number)
                } else {
                    number.to_string()
                };
                let vars: HashMap<&str, String> = [
                    ("number", number_str.clone()),
                    ("part_title", title.clone()),
                ]
                .into_iter()
                .collect();
                let text = render(&part_template, &vars);
                stack.push((link, Vec::new()));
                out.push(TocEntry {
                    link,
                    title: text,
                    is_part: true,
                    children: Vec::new(),
                });
                link += 1;
            }
            Entry::Chapter { doc, numbered, use_title, .. } => {
                for block in &doc.blocks {
                    if let Block::Heading { level: 1, inline } = block {
                        let title = heading_text(inline);
                        let title = if *use_title { title } else { String::new() };
                        let text = if *numbered {
                            chapter_number += 1;
                            let number_str = if roman_chapter {
                                roman(chapter_number)
                            } else {
                                chapter_number.to_string()
                            };
                            let vars: HashMap<&str, String> = [
                                ("number", number_str),
                                ("chapter_title", title.clone()),
                            ]
                            .into_iter()
                            .collect();
                            render(&chapter_template, &vars)
                        } else {
                            title.clone()
                        };
                        out.push(TocEntry {
                            link,
                            title: text,
                            is_part: false,
                            children: Vec::new(),
                        });
                        link += 1;
                    }
                }
            }
        }
    }
    let _ = (chapter_name, part_name);
    out
}
