    errors: &mut Vec<CrowbookError>,
) -> Result<String, CrowbookError> {
    let config = &book.config;
    let lang = config.get_str_or("lang", "en");
    let author = config.get_str_or("author", "");
    let title = config.get_str_or("title", "");
    let subtitle = config.get_str("subtitle");
    let mut head = String::new();
    head.push_str("<!DOCTYPE html>\n");
    head.push_str(&format!("<html lang=\"{}\">\n", escape_attr(&lang)));
    head.push_str("  <head>\n");
    head.push_str("    <meta charset=\"utf-8\">\n");
    head.push_str("    <meta name=\"generator\" content=\"crowbook\">\n");
    head.push_str("    <meta name=\"viewport\" content=\"width=device-width\">\n");
    head.push_str(&format!(
        "    <meta name=\"author\" content=\"{}\">\n",
        escape_attr(&author)
    ));
    match config.get_str("html.icon") {
        Some(icon) => {
            let data = std::fs::read(&icon).map_err(|_| {
                CrowbookError::error(
                    Source::none(),
                    config.localization().message(
                        "could_not_find_file",
                        &[("file", format!("./{}", icon)), ("what", "icon".to_string())],
                    ),
                )
            })?;
            head.push_str(&format!(
                "    <link rel = \"icon\" href = \"data:{};base64,{}\">\n",
                mime_of(&icon),
                base64(&data)
            ));
        }
        None => head.push_str("    \n"),
    }
    head.push_str(&format!("    <title>{}</title>\n", escape_attr(&title)));
    head.push_str("    <style type = \"text/css\">\n      ");
    head.push_str(&html_css(config));
    head.push_str("\n    </style>\n");
    head.push_str("    <style type = \"text/css\" media = \"print\">\n      ");
    head.push_str(PRINT_CSS);
    head.push_str("\n    </style>\n");
    head.push_str("    \n   <script>\n    ");
    head.push_str(HTML_JS);
    head.push_str("   </script>\n\n\n  </head>\n  ");
    // body
    let mut body = String::new();
    body.push_str("<body>\n    \n");
    // ld+json
    body.push_str("<script type = 'application/ld+json'>\n{\n");
    body.push_str("    \"@context\": \"http://schema.org/\",\n");
    body.push_str("    \"@type\": \"Book\",\n");
    body.push_str(&format!("    \"author\": \"{}\",\n", escape_attr(&author)));
    body.push_str(&format!("    \"name\": \"{}\",\n", escape_attr(&title)));
    let field = |name: &str, value: &Option<String>, json_key: &str| -> String {
        match value {
            Some(v) => format!("    \"{}\": \"{}\",\n", json_key, escape_attr(v)),
            None => "    \n".to_string(),
        }
    };
    body.push_str(&field("alternateName", &subtitle, "alternateName"));
    body.push_str(&field("keywords", &config.get_str("subject"), "keywords"));
    body.push_str(&field("license", &config.get_str("license"), "license"));
    body.push_str(&field(
        "about",
        &config.get_str("description"),
        "about",
    ));
    body.push_str(&format!("    \"inLanguage\": \"{}\"\n", escape_attr(&lang)));
    body.push_str("}\n</script>\n");
    body.push_str("    ");
    let toc_entries = toc(config, &book.entries);
    if book.chapter_count() > 1 {
        body.push_str(&nav_html(&toc_entries, &title));
    }
    body.push_str("\n\n    <div id = \"content\">\n      \n      <div id = \"page\">\n        <header>\n\n");
    body.push_str("          <div id = \"menu\">\n\t        \n");
    if config.get_str("html.icon").is_some() {
        body.push_str("            <img id = \"menu-button\" onclick=\"toggle();\"\n                 src=\"data:image/svg+xml;base64,");
        body.push_str(&base64(MENU_SVG.as_bytes()));
        body.push_str("\"\n                 alt = \"");
        body.push_str(&escape_attr(&config.localization().get("toc")));
        body.push_str("\" title = \"");
        body.push_str(&escape_attr(&config.localization().get("toc")));
        body.push_str("\" />\n          \n");
    }
    body.push_str("          </div>\n");
    body.push_str(&format!(
        "\t  <h2 class=\"author\">{}</h2>\n",
        escape_attr(&author)
    ));
    body.push_str(&format!(
        "          <h1 id = \"link-0\" class=\"title\" >{}</h1>\n",
        escape_attr(&title)
    ));
    body.push_str("\t  ");
    match &subtitle {
        Some(s) => body.push_str(&format!(
            "<h2 class = \"subtitle\">{}</h2>",
            escape_attr(s)
        )),
        None => {}
    }
    body.push_str("\n\t  \n        </header>\n");
    if config.get_bool("rendering.inline_toc", false) {
        let toc_name = config.get_str_or("rendering.inline_toc.name", "{{loc_toc}}");
        let mut vars: HashMap<&str, String> = HashMap::new();
        vars.insert(
            "loc_toc",
            config.localization().get("toc"),
        );
        let name = crate::render::template::render(&toc_name, &vars);
        body.push_str("\n        ");
        body.push_str(&toc_html(&toc_entries, &name));
    }
    // chapters
    let mut renderer = crate::render::html::Renderer::new(
        config,
        false,
        String::new(),
        book.files(),
    );
    for entry in &book.entries {
        match entry {
            Entry::Part { title: part_title, number } => {
                let part_name = config.get_str_or(
                    "rendering.part",
                    &config.localization().get("part"),
                );
                let number_str = if config.get_bool("rendering.part.roman_numerals", true) {
                    roman(*number)
                } else {
                    number.to_string()
                };
                let link = renderer.link;
                renderer.link += 1;
                body.push_str(&format!(
                    "<div id = \"chapter-{}\" class = \"chapter\">\n  <h2 class = 'part'>{} {}</h2> <h1 id = 'link-{}' class = 'part'>{}</h1>\n</div>",
                    renderer.para,
                    escape_attr(&part_name),
                    escape_attr(&number_str),
                    link,
                    escape_attr(part_title)
                ));
                renderer.para += 1;
            }
            Entry::Chapter { doc, .. } => {
                let mut chapter = String::new();
                chapter.push_str(&format!(
                    "<div id = \"chapter-{}\" class = \"chapter\">\n  ",
                    renderer.para
                ));
                renderer.para += 1;
                // render the blocks, replacing level-1 headings
                chapter.push_str(&render_chapter(config, &mut renderer, doc));
                chapter.push_str("\n</div>");
                body.push_str(&chapter);
            }
        }
    }
    let _ = errors;
    let mut out = head;
    out.push_str(&body);
    out.push_str("\n\n      </div>\n      \n    </div>\n  </body>\n</html>\n");
    Ok(out)
}

/// Renders the blocks of a chapter, using the chapter heading template for
/// level-1 headings.
fn render_chapter(
    config: &Config,
    renderer: &mut crate::render::html::Renderer,
    doc: &Doc,
) -> String {
    let chapter_template = config.get_str_or(
        "html.chapter.template",
        "<h1 id = 'link-{{link}}'>{% if has_number %}<span class = 'chapter-header'>{{header}} {{number}}</span>{% if has_title %}<br />{% endif %}{% endif %}{{title}}</h1>",
    );
    let chapter_name = config.get_str_or(
        "rendering.chapter",
        &config.localization().get("chapter"),
    );
    let roman = config.get_bool("rendering.chapter.roman_numerals", false);
    let num_depth = config.get_int("rendering.num_depth", 1);
    let mut out = String::new();
    let mut first_para = true;
    for block in &doc.blocks {
        match block {
            Block::Heading { level: 1, inline } => {
                let number = if num_depth >= 1 {
                    renderer.chapter_number
                } else {
                    0
                };
                renderer.chapter_number += 1;
                let title = heading_text(inline);
                let vars: HashMap<&str, String> = [
                    ("link", renderer.link.to_string()),
                    ("header", chapter_name.clone()),
                    (
                        "number",
                        if roman {
                            roman(number)
                        } else {
                            number.to_string()
                        },
                    ),
                    ("title", title.clone()),
                    ("has_number", if number > 0 { "1" } else { "" }.to_string()),
                    ("has_title", if title.is_empty() { "" } else { "1" }.to_string()),
                ]
                .into_iter()
                .collect();
                let _ = &chapter_template;
                let link = renderer.link;
                renderer.link += 1;
                let has_number = number > 0;
                let mut h = format!("<h1 id = 'link-{link}'>");
                if has_number {
                    h.push_str(&format!(
                        "<span class = 'chapter-header'>{} {}</span>",
                        escape_attr(&chapter_name),
                        if roman {
                            roman(number)
                        } else {
                            number.to_string()
                        }
                    ));
                    if !title.is_empty() {
                        h.push_str("<br />");
                    }
                }
                h.push_str(&escape_attr(&title));
                h.push_str("</h1>");
                out.push_str(&h);
            }
            Block::Heading { level, inline } => {
                out.push_str(&renderer.render_block(block));
                let _ = (level, inline);
            }
            Block::Paragraph(inlines) => {
                out.push_str(&renderer.render_block(block));
                let _ = inlines;
            }
            other => {
                out.push_str(&renderer.render_block(other));
            }
        }
        let _ = first_para;
        first_para = false;
    }
    out
}
