/// Renders the blocks of a chapter, using the chapter heading template for
/// level-1 headings.
fn render_chapter(
    config: &Config,
    renderer: &mut crate::render::html::Renderer,
    doc: &Doc,
) -> String {
    let chapter_template = config.get_str_or(
        "html.chapter.template",
        "<h1 id = 'link-{{link}}'>{% if has_number %}<span class = 'chapter-header'>{{header}} {{number}}</span>{% if has_title %}<br />{% endif %}{% endif %}{{title}}</h1>",
    );
    let chapter_name = config.get_str_or(
        "rendering.chapter",
        &config.localization().get("chapter"),
    );
    let roman = config.get_bool("rendering.chapter.roman_numerals", false);
    let num_depth = config.get_int("rendering.num_depth", 1);
    let mut out = String::new();
    let mut first_para = true;
    for block in &doc.blocks {
        match block {
            Block::Heading { level: 1, inline } => {
                let number = if num_depth >= 1 {
                    renderer.chapter_number
                } else {
                    0
                };
                renderer.chapter_number += 1;
                let title = heading_text(inline);
                let vars: HashMap<&str, String> = [
                    ("link", renderer.link.to_string()),
                    ("header", chapter_name.clone()),
                    (
                        "number",
                        if roman {
                            roman(number)
                        } else {
                            number.to_string()
                        },
                    ),
                    ("title", title.clone()),
                    ("has_number", if number > 0 { "1" } else { "" }.to_string()),
                    ("has_title", if title.is_empty() { "" } else { "1" }.to_string()),
                ]
                .into_iter()
                .collect();
                let _ = &chapter_template;
                let link = renderer.link;
                renderer.link += 1;
                let has_number = number > 0;
                let mut h = format!("<h1 id = 'link-{link}'>");
                if has_number {
                    h.push_str(&format!(
                        "<span class = 'chapter-header'>{} {}</span>",
                        escape_attr(&chapter_name),
                        if roman {
                            roman(number)
                        } else {
                            number.to_string()
                        }
                    ));
                    if !title.is_empty() {
                        h.push_str("<br />");
                    }
                }
                h.push_str(&escape_attr(&title));
                h.push_str("</h1>");
                out.push_str(&h);
            }
            Block::Heading { level, inline } => {
                out.push_str(&renderer.render_block(block));
                let _ = (level, inline);
            }
            Block::Paragraph(inlines) => {
                out.push_str(&renderer.render_block(block));
                let _ = inlines;
            }
            other => {
                out.push_str(&renderer.render_block(other));
            }
        }
        let _ = first_para;
        first_para = false;
    }
    out
}
