/// Base64-encodes a byte slice.
fn base64(data: &[u8]) -> String {
    const TABLE: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::new();
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = *chunk.get(1).unwrap_or(&0) as u32;
        let b2 = *chunk.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(TABLE[(n >> 18) as usize & 63] as char);
        out.push(TABLE[(n >> 12) as usize & 63] as char);
        if chunk.len() > 1 {
            out.push(TABLE[(n >> 6) as usize & 63] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(TABLE[n as usize & 63] as char);
        } else {
            out.push('=');
        }
    }
    out
}

/// Returns the mime type of a file, based on its extension.
fn mime_of(path: &str) -> &'static str {
    let ext = Path::new(path)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("");
    match ext {
        "png" => "image/png",
        "jpg" | "jpeg" => "image/jpeg",
        "gif" => "image/gif",
        "svg" => "image/svg+xml",
        "css" => "text/css",
        "js" => "text/javascript",
        "ttf" => "font/ttf",
        "otf" => "font/otf",
        "woff" => "font/woff",
        _ => "application/octet-stream",
    }
}

/// Renders the table of contents as HTML.
fn toc_html(entries: &[TocEntry], toc_name: &str) -> String {
    let mut out = String::new();
    out.push_str(&format!("        <div id = \"toc\">\n  <h1>{}</h1>\n", toc_name));
    out.push_str("      <ul>\n");
    fn render_items(items: &[TocEntry], out: &mut String, indent: usize) {
        let pad = " ".repeat(indent);
        for item in items {
            if item.children.is_empty() {
                out.push_str(&format!(
                    "{pad}<li><a href=\"#link-{link}\">{title}</a></li>\n",
                    pad = pad,
                    link = item.link,
                    title = escape_attr(&item.title)
                ));
            } else {
                out.push_str(&format!(
                    "{pad}<li>\n{pad}  <a href=\"#link-{link}\">{title}</a>\n",
                    pad = pad,
                    link = item.link,
                    title = escape_attr(&item.title)
                ));
                out.push_str(&format!("{pad}  <ul>\n"));
                render_items(&item.children, out, indent + 4);
                out.push_str(&format!("{pad}  </ul>\n"));
                out.push_str(&format!("{pad}</li>\n"));
            }
        }
    }
    render_items(entries, &mut out, 6);
    out.push_str("    </ul>\n</div>\n");
    out
}

/// Renders the table of contents for the navigation menu.
fn nav_html(entries: &[TocEntry], title: &str) -> String {
    let mut out = String::new();
    out.push_str("    <nav id = \"nav\">\n      \n      <div id = \"nav-title\">\n");
    out.push_str(&format!(
        "        <h2><a href = \"#link-0\">{}</a></h2>\n",
        escape_attr(title)
    ));
    out.push_str("      </div>\n          <ul>\n");
    fn flat(items: &[TocEntry], out: &mut String) {
        for item in items {
            out.push_str(&format!(
                "      <li><a href=\"#link-{link}\">{title}</a></li>\n",
                link = item.link,
                title = escape_attr(&item.title)
            ));
            flat(&item.children, out);
        }
    }
    flat(entries, &mut out);
    out.push_str("    </ul>\n    </nav>\n    ");
    out
}

