{"command": "cat >> src/lib/book.rs <<'RSEOF'

/// Finds the line of a key in the book configuration file.
pub fn first_line(file: &str, key: &str) -> Option<usize> {
    let text = std::fs::read_to_string(file).ok()?;
    first_line_of(&text, key)
}

/// Parses a single Markdown file, using the YAML block at its beginning for
/// the options.
pub fn parse_single(
    content: &str,
    file: &str,
    config: &mut Config,
    entries: &mut Vec<Entry>,
    errors: &mut Vec<CrowbookError>,
) {
    let mut text = content.to_string();
    if let Some(rest) = content.strip_prefix("---\n") {
        if let Some(pos) = rest.find("\n---") {
            let yaml = &rest[..pos];
            let after = &rest[pos + 4..];
            match crate::yaml::parse(yaml) {
                Ok(node) => {
                    if let crate::yaml::Yaml::Hash(pairs) = node.value {
                        for (key, value) in pairs {
                            let key = match key {
                                crate::yaml::Yaml::String(s) => s,
                                _ => continue,
                            };
                            let line = first_line_of(yaml, &key);
                            let source = Source::new(file, line);
                            if let Err(e) = config.set(&key, value, &source) {
                                errors.push(e);
                            }
                        }
                    }
                }
                Err(e) => {
                    errors.push(CrowbookError::error(
                        Source::new(file, Some(e.line)),
                        format!("YAML block was not valid YAML: {}", e),
                    ));
                }
            }
            text = after.trim_start_matches('\n').to_string();
        }
    }
    let doc = Parser::new(&text, config).parse_document();
    entries.push(Entry::Chapter {
        name: file.to_string(),
        numbered: true,
        use_title: true,
        doc,
        numbers: Vec::new(),
    });
}

/// Prints the statistics of the book.
pub fn print_stats(entries: &[Entry]) {
    let mut out = String::new();
    out.push_str(&format!(
        "{:<18}{:>5}{:>11}{:>12}\n",
        "Chapter", "Chars", "Words", "Chars/Word"
    ));
    out.push_str("---------\n");
    let mut total_chars = 0;
    let mut total_words = 0;
    let mut names = Vec::new();
    for entry in entries {
        if let Entry::Chapter { name, doc, .. } = entry {
            let (chars, words) = count(doc);
            out.push_str(&format!(
                "{:<18}{:>5}{:>11}{:>12}\n",
                name,
                chars,
                words,
                if words == 0 {
                    format!("NaN")
                } else {
                    format!("{:.2}", chars as f64 / words as f64)
                }
            ));
            total_chars += chars;
            total_words += words;
            names.push(name.clone());
        }
    }
    out.push_str("---------\n");
    out.push_str(&format!(
        "{:<18}{:>5}{:>11}{:>12}\n",
        "TOTAL:",
        total_chars,
        total_words,
        if total_words == 0 {
            "NaN".to_string()
        } else {
            format!("{:.2}", total_chars as f64 / total_words as f64)
        }
    ));
    out.push('\n');
    print!("{}", out);
    let _ = names;
}

/// Counts the characters and the words of a document.
fn count(doc: &Doc) -> (usize, usize) {
    let mut text = String::new();
    fn walk(blocks: &[Block], text: &mut String) {
        for block in blocks {
            match block {
                Block::Heading { inline, .. } | Block::Paragraph(inline) => {
                    inlines(inline, text)
                }
                Block::Quote(b) => walk(b, text),
                Block::Bullet(items) | Block::Ordered { items, .. } => {
                    for item in items {
                        walk(item, text)
                    }
                }
