{"command": "cat > src/lib/render/template.rs <<'RSEOF'
//! A very small template engine, similar to the one Crowbook uses.

use std::collections::HashMap;

/// Renders `template`, substituting `{{name}}` variables and
/// `{% if name %}…{% endif %}` conditions.
pub fn render(template: &str, vars: &HashMap<&str, String>) -> String {
    let mut out = String::new();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '{' && chars.get(i + 1) == Some(&'%') {
            // a tag
            let mut j = i + 2;
            while j + 1 < chars.len() && !(chars[j] == '%' && chars[j + 1] == '}') {
                j += 1;
            }
            if j + 1 < chars.len() {
                let tag: String = chars[i + 3..j].iter().collect();
                let tag = tag.trim();
                if let Some(rest) = tag.strip_prefix("if ") {
                    let truth = condition(rest.trim(), vars);
                    let (body, end) = find_block(&chars, j + 2);
                    if truth {
                        out.push_str(&render(&body, vars));
                    }
                    i = end;
                    continue;
                }
                i = j + 2;
                continue;
            }
            out.push(chars[i]);
            i += 1;
        } else if chars[i] == '{' && chars.get(i + 1) == Some(&'{') {
            // a variable
            let mut j = i + 2;
            while j + 1 < chars.len() && !(chars[j] == '}' && chars[j + 1] == '}') {
                j += 1;
            }
            if j + 1 < chars.len() {
                let name: String = chars[i + 2..j].iter().collect();
                let name = name.trim();
                out.push_str(vars.get(name).map(|s| s.as_str()).unwrap_or(""));
                i = j + 2;
                continue;
            }
            out.push(chars[i]);
            i += 1;
        } else {
            out.push(chars[i]);
            i += 1;
        }
    }
    out
}

fn condition(cond: &str, vars: &HashMap<&str, String>) -> bool {
    if let Some(pos) = cond.find('|') {
        let name = cond[..pos].trim();
        let rest = cond[pos + 1..].trim();
        if let Some(value) = rest.strip_prefix("eq:") {
            let value = value.trim().trim_matches('"');
            return vars.get(name).map(|s| s.as_str()) == Some(value);
        }
    }
    !vars.get(cond).map(|s| s.is_empty()).unwrap_or(true)
}

/// Returns the body of an `{% if %}` block starting at `start`, and the index
/// just after the `{% endif %}`.
fn find_block(chars: &[char], start: usize) -> (String, usize) {
    let mut i = start;
    let mut depth = 0;
    while i < chars.len() {
        if chars[i] == '{' && chars.get(i + 1) == Some(&'%') {
            let mut j = i + 2;
            while j + 1 < chars.len() && !(chars[j] == '%' && chars[j + 1] == '}') {
                j += 1;
            }
            if j + 1 < chars.len() {
                let tag: String = chars[i + 3..j].iter().collect();
                let tag = tag.trim();
                if tag.starts_with("if ") {
                    depth += 1;
                } else if tag == "endif" {
                    if depth == 0 {
                        let body: String = chars[start..i].iter().collect();
                        return (body, j + 2);
                    }
                    depth -= 1;
                }
                i = j + 2;
                continue;
            }
        }
        i += 1;
    }
    (chars[start..].iter().collect(), chars.len())
}
