fn escape_html(s: &str) -> String {
    crate::render::html::escape(s)
}

fn inlines_to_html(inlines: &[Inline]) -> String {
    let mut out = String::new();
    for i in inlines {
        out.push_str(&inline_to_html(i));
    }
    out
}

fn inline_to_html(inline: &Inline) -> String {
    match inline {
        Inline::Text(t) => escape_html(t),
        Inline::Em(i) => format!("<em>{}</em>", inlines_to_html(i)),
        Inline::Strong(i) => format!("<b>{}</b>", inlines_to_html(i)),
        Inline::Del(i) => format!("<del>{}</del>", inlines_to_html(i)),
        Inline::Code(c) => format!("<code>{}</code>", escape_html(c)),
        Inline::SoftBreak => " ".to_string(),
        Inline::HardBreak => "<br />\\n".to_string(),
        Inline::Note(l) => format!("\\u{{NOTE}}{}\\u{{/NOTE}}", l),
        Inline::Sup(i) => format!("<sup>{}</sup>", inlines_to_html(i)),
        Inline::Sub(i) => format!("<sub>{}</sub>", inlines_to_html(i)),
        Inline::Link { url, title, text } => {
            let title_attr = match title {
                Some(t) => format!(" title = \\"{}\\"", crate::render::html::escape_attr(t)),
                None => String::new(),
            };
            format!(
                "<a href = \\"{}\\"{}>{}</a>",
                escape_html(url),
                title_attr,
                inlines_to_html(text)
            )
        }
        Inline::Image { url, title, alt } => format!(
            "<img src = \\"{}\\" title = \\"{}\\" alt = \\"{}\\" />",
            escape_html(url),
            crate::render::html::escape_attr(title.as_deref().unwrap_or("")),
            crate::render::html::escape_attr(alt)
        ),
    }
}

/// Parses a rendered HTML fragment back into inline elements.
fn html_to_inlines(html: &str) -> Vec<Inline> {
    let mut out = Vec::new();
    let chars: Vec<char> = html.chars().collect();
    let mut i = 0;
    let mut buf = String::new();
    while i < chars.len() {
        if chars[i] == '\\u{NOTE}' {
            flush(&mut buf, &mut out);
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '\\u{NOTE}' {
                j += 1;
            }
            let label: String = chars[i + 1..j.min(chars.len())].iter().collect();
            out.push(Inline::Note(label));
            i = j + 1;
            continue;
        }
        if chars[i] == '<' {
            // find the matching tag
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '>' {
                j += 1;
            }
            if j >= chars.len() {
                buf.push(chars[i]);
                i += 1;
                continue;
            }
            let tag: String = chars[i..j + 1].iter().collect();
            let name: String = tag[1..tag.len() - 1]
                .split_whitespace()
                .next()
                .unwrap_or("")
                .to_string();
            if tag.ends_with("/>") {
                // void element
                flush(&mut buf, &mut out);
                out.push(Inline::Text(tag));
                i = j + 1;
                continue;
            }
            let close = format!("</{}>", name);
            let close_pos = html[i + tag.len()..].find(&close);
            match close_pos {
                Some(off) => {
                    flush(&mut buf, &mut out);
                    let inner_start = i + tag.len();
                    let inner_end = inner_start + off;
                    let inner: String = chars[inner_start..inner_end].iter().collect();
                    let inner_inlines = html_to_inlines(&inner);
                    match name.as_str() {
                        "em" => out.push(Inline::Em(inner_inlines)),
                        "b" => out.push(Inline::Strong(inner_inlines)),
                        "del" => out.push(Inline::Del(inner_inlines)),
                        "sup" => out.push(Inline::Sup(inner_inlines)),
                        "sub" => out.push(Inline::Sub(inner_inlines)),
                        "code" => out.push(Inline::Code(unescape_html(&inner))),
                        "br" => out.push(Inline::HardBreak),
                        "a" => {
                            let (url, title) = parse_a_tag(&tag);
                            out.push(Inline::Link {
                                url,
                                title,
                                text: inner_inlines,
                            });
                        }
                        "img" => {
                            let (src, title, alt) = parse_img_tag(&tag);
                            out.push(Inline::Image {
                                url: src,
                                title,
                                alt,
                            });
                        }
                        _ => out.push(Inline::Text(tag)),
                    }
                    i = inner_end + close.len();
                }
                None => {
                    buf.push(chars[i]);
                    i += 1;
                }
            }
        } else {
            buf.push(chars[i]);
            i += 1;
        }
    }
    flush(&mut buf, &mut out);
    out
}

fn unescape_html(s: &str) -> String {
    s.replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\\"")
        .replace("&#160;", "\\u{a0}")
        .replace("&amp;", "&")
}

fn attr_of(tag: &str, name: &str) -> Option<String> {
    let pattern = format!("{} = \\"", name);
    let pos = tag.find(&pattern)?;
    let rest = &tag[pos + pattern.len()..];
    let end = rest.find('"')?;
    Some(rest[..end].to_string())
}

fn parse_a_tag(tag: &str) -> (String, Option<String>) {
    let url = attr_of(tag, "href").unwrap_or_default();
    let title = attr_of(tag, "title");
    (url, title)
}

fn parse_img_tag(tag: &str) -> (String, Option<String>, String) {
    let src = attr_of(tag, "src").unwrap_or_default();
    let title = attr_of(tag, "title");
    let alt = attr_of(tag, "alt").unwrap_or_default();
    (src, title, alt)
}

fn flush_out(buf: &mut String, out: &mut String) {
    if !buf.is_empty() {
        out.push_str(&escape_html(buf));
        buf.clear();
    }
}

