/// Finds the first occurrence of `c` that is not escaped by a backslash.
fn find_unescaped(s: &str, c: char) -> Option<usize> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '\\\\' {
            i += 2;
            continue;
        }
        if chars[i] == c {
            return Some(chars[..i].iter().map(|c| c.len_utf8()).sum());
        }
        i += 1;
    }
    None
}

