//! Rendering to LaTeX.

use crate::config::{Config, CrowbookError};
use crate::parser::{Block, Doc, Inline};
use crate::render::template::render as render_template;
use std::collections::HashMap;

const TEMPLATE: &str = include_str!("../../assets/tex.tex");

/// Escapes a string for LaTeX.
pub fn escape(s: &str) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '-' => {
                out.push('-');
                if chars.get(i + 1) == Some(&'-') {
                    out.push_str("{}");
                }
            }
            '!' => out.push_str("!{}"),
            '#' => out.push_str("\\#"),
            '$' => out.push_str("\\$"),
            '%' => out.push_str("\\%"),
            '&' => out.push_str("\\&"),
            '<' => out.push_str("\\textless{}"),
            '>' => out.push_str("\\textgreater{}"),
            '[' => out.push_str("{[}"),
            ']' => out.push_str("{]}"),
            '\\' => out.push_str("\\textbackslash{}"),
            '^' => out.push_str("\\textasciicircum{}"),
            '_' => out.push_str("\\_"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '~' => out.push_str("\\textasciitilde{}"),
            _ => out.push(c),
        }
        i += 1;
    }
    out
}

pub struct TexRenderer<'a> {
    pub config: &'a Config,
    pub chapter: usize,
    pub note: usize,
    pub images: Vec<String>,
    pub notes: Vec<(String, Vec<Block>)>,
    pub link_defs: Vec<(String, String, Option<String>)>,
    pub source: String,
    pub errors: Vec<(String, String)>,
    pub first_para: bool,
}

impl<'a> TexRenderer<'a> {
    pub fn new(config: &'a Config) -> TexRenderer<'a> {
        TexRenderer {
            config,
            chapter: 0,
            note: 0,
            images: Vec::new(),
            notes: Vec::new(),
            link_defs: Vec::new(),
            source: String::new(),
            errors: Vec::new(),
            first_para: true,
        }
    }

    pub fn render_blocks(&mut self, blocks: &[Block]) -> String {
        let mut out = String::new();
        for block in blocks {
            out.push_str(&self.render_block(block));
        }
        out
    }

    fn heading_command(&self, level: usize) -> &'static str {
        let class = self.config.get_str_or("tex.class", "book");
        match (class.as_str(), level) {
            ("book", 1) => "\\chapter",
            ("book", 2) => "\\section",
            ("book", 3) => "\\subsection",
            ("book", 4) => "\\subsubsection",
            (_, 1) => "\\section",
            (_, 2) => "\\subsection",
            (_, 3) => "\\subsubsection",
            (_, 4) => "\\subsubsection",
            _ => "\\paragraoh",
        }
    }

    pub fn render_block(&mut self, block: &Block) -> String {
        match block {
            Block::Heading { level, inline } => {
                let cmd = self.heading_command(*level);
                let text = self.render_inlines(inline);
                if *level == 1 {
                    let n = self.chapter;
                    self.chapter += 1;
                    format!("{}{{{}}}\n\\label{{chapter-{}}}\n", cmd, text, n)
                } else {
                    format!("{}{{{}}}\n", cmd, text)
                }
            }
            Block::Paragraph(inlines) => {
                let text = self.render_inlines(inlines);
                let n = self.note;
                let _ = n;
                let mut out = String::new();
                if self.first_para && self.config.get_bool("rendering.initials", false) {
                    self.first_para = false;
                    if let Some(Inline::Text(t)) = inlines.first() {
                        if let Some(c) = t.chars().next() {
                            // lettrine: the first letter, then the rest
                            let rest: String = t.chars().skip(1).collect();
                            let mut new_inlines: Vec<Inline> = Vec::new();
                            if !rest.is_empty() {
                                new_inlines.push(Inline::Text(rest));
                            }
                            new_inlines.extend(inlines.iter().skip(1).cloned());
                            let inner = self.render_inlines(&new_inlines);
                            out.push_str(&format!("\\lettrine{{{}}}{{{}}}\n\n", c, inner));
                            return out;
                        }
                    }
                }
                format!("{}\n\n", text)
            }
            Block::Quote(blocks) => {
                let inner = self.render_blocks(blocks);
                format!("\\begin{{mdblockquote}}\n{}\n\\end{{mdblockquote}}\n", inner)
            }
            Block::Bullet(items) => {
                let mut out = String::from("\\begin{itemize}\n");
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("\\item {}\n\n", inner));
                }
                out.push_str("\\end{itemize}");
                out
            }
            Block::Ordered { start, items } => {
                let mut out = String::from("\\begin{enumerate}\n");
                if *start != 1 {
                    out.push_str(&format!("\\setcounter{{enumi}}{{{}}}\n", start - 1));
                }
                for item in items {
                    let inner = self.render_blocks(item);
                    out.push_str(&format!("\\item {}\n\n", inner));
                }
                out.push_str("\\end{enumerate}");
                out
            }
            Block::DefList(entries) => {
                let mut out = String::from(
                    "\\begin{description}[style=nextline, labelwidth=0pt]\n",
                );
                for (term, blocks) in entries {
                    let t = self.render_inlines(term);
                    out.push_str(&format!("\\item[{}]\n", t));
                    let b = self.render_blocks(blocks);
                    out.push_str(&b);
                }
                out.push_str("\\end{description}");
                out
            }
            Block::Code { text, .. } => {
                let highlighted = crate::render::tex::highlight_tex(text, self.config);
                format!("\\begin{{mdcodeblock}}\n{{{}}}\n\\end{{mdcodeblock}}", highlighted)
            }
            Block::Table { head, rows } => {
                let mut cols = String::new();
                for _ in head {
                    cols.push('|');
                    cols.push('X');
                }
                cols.push('|');
                let mut out = format!("\\begin{{mdtable}}{{{}}}\n\\hline\n", cols);
                for cell in head {
                    let c = self.render_inlines(cell);
                    out.push_str(&format!("{} & ", c));
                }
                out.push_str("\\\\ \n\\hline\n");
                for row in rows {
                    for cell in row {
                        let c = self.render_inlines(cell);
                        out.push_str(&format!("{} & ", c));
                    }
                    out.push_str("\\\\ \n");
                }
                out.push_str("\n\\hline\n\\end{mdtable}\n\n");
                out
            }
            Block::Rule => "\\mdrule\n".to_string(),
            Block::NoteDef { label, blocks } => {
                self.notes.push((label.clone(), blocks.clone()));
                String::new()
            }
            Block::LinkDef { .. } => String::new(),
            Block::Yaml(_) => String::new(),
        }
    }

    pub fn render_inlines(&mut self, inlines: &[Inline]) -> String {
        let mut out = String::new();
        for inline in inlines {
            out.push_str(&self.render_inline(inline));
        }
        out
    }

    pub fn render_inline(&mut self, inline: &Inline) -> String {
        match inline {
            Inline::Text(t) => {
                let cleaned = crate::parser::clean(t, self.config);
                escape(&crate::render::html::unescape(&cleaned))
            }
            Inline::Em(i) => format!("\\emph{{{}}}", self.render_inlines(i)),
            Inline::Strong(i) => format!("\\mdstrong{{{}}}", self.render_inlines(i)),
            Inline::Del(i) => format!("\\sout{{{}}}", self.render_inlines(i)),
            Inline::Code(c) => {
                let cleaned = crate::parser::clean(c, self.config);
                format!("\\mdcode{{{}}}", escape(&crate::render::html::unescape(&cleaned)))
            }
            Inline::SoftBreak => " ".to_string(),
            Inline::HardBreak => "\\mdhardbreak\n".to_string(),
            Inline::Note(label) => {
                let n = self.note + 1;
                self.note += 1;
                if let Some((_, blocks)) = self
                    .notes
                    .iter()
                    .find(|(l, _)| l == label)
                    .cloned()
                {
                    self.notes_to_render.push((label.clone(), blocks));
                }
                format!("\\footnotemark[{}]", label)
            }
            Inline::Sup(i) => format!("\\textsuperscript{{{}}}", self.render_inlines(i)),
            Inline::Sub(i) => format!("\\textsubscript{{{}}}", self.render_inlines(i)),
            Inline::Link { url, title, text } => {
                let t = self.render_inlines(text);
                let u = escape(url);
                let _ = title;
                if crate::parser::is_local(url) && self.config.get_bool("tex.links_as_footnotes", true)
                {
                    format!("\\href{{{}}}{{{}}}\\protect\\footnote{{\\url{{{}}}}}", u, t, u)
                } else {
                    format!("\\href{{{}}}{{{}}}", u, t)
                }
            }
            Inline::Image { url, title, alt } => {
                let _ = title;
                let _ = alt;
                let n = self.images.len();
                let ext = std::path::Path::new(url)
                    .extension()
                    .and_then(|e| e.to_str())
                    .unwrap_or("");
                let name = format!("images/image_{}.{}", n, ext);
                self.images.push(format!("{}|{}", name, url));
                format!("\\mdimage{{{}}}", name)
            }
        }
    }

    pub notes_to_render: Vec<(String, Vec<Block>)>,
}

/// Highlights code for LaTeX output.
pub fn highlight_tex(text: &str, _config: &Config) -> String {
    let mut out = String::new();
    for line in text.split('\n') {
        out.push_str(&format!(
            "{{\\sloppy \\textcolor[rgb]{{0.19607843, 0.19607843, 0.19607843}}{{\\texttt{{{}}}}}}\\\\{{}}\n",
            tex_code(line)
        ));
    }
    out
}

fn tex_code(line: &str) -> String {
    let mut out = String::new();
    let chars: Vec<char> = line.chars().collect();
    for (i, c) in chars.iter().enumerate() {
        match c {
            ' ' => out.push_str("\\hphantom{ }\\allowbreak{}"),
            '\\' => out.push_str("\\textbackslash{}"),
            '{' => out.push_str("\\{"),
            '}' => out.push_str("\\}"),
            '%' => out.push_str("\\%"),
            '#' => out.push_str("\\#"),
            '$' => out.push_str("\\$"),
            '&' => out.push_str("\\&"),
            '_' => out.push_str("\\_"),
            '^' => out.push_str("\\textasciicircum{}"),
            '~' => out.push_str("\\textasciitilde{}"),
            _ => out.push(*c),
        }
        let _ = i;
    }
    out
}
