        let top = config.get_str_or("tex.margin.top", "2cm");
        let bottom = config.get_str_or("tex.margin.bottom", "1.5cm");
        format!(
            "% Included if the stdpage option if set to false\\n\\\\usepackage[{}, top={}, bottom={},\\n  left={},right={} {{}}]{{geometry}} % Set dimensions/margins of the page",
            config.get_str_or("tex.paper.size", "a5paper"),
            top,
            bottom,
            left,
            right
        )
        .replace(" {{}}]", "]")
    };
    let date = config.get_str_or("date", "");
    let subtitle = config.get_str_or("subtitle", "");
    let version = match config.get_str("version") {
        Some(v) => format!("{{, {}}}", v),
        None => String::new(),
    };
    let copyright = if author.is_empty() {
        String::new()
    } else {
        "\\@author".to_string()
    };
    let license = match config.get_str("license") {
        Some(l) => format!("    {{{}\\\\\\\\[5mm]}}", l),
        None => String::new(),
    };
    let date_line = if date.is_empty() {
        String::new()
    } else {
        "      \\\\@date".to_string()
    };
    let mut vars: HashMap<&str, String> = HashMap::new();
    vars.insert("docclass", docclass);
    vars.insert("babel", babel.to_string());
    vars.insert("author", author.clone());
    vars.insert("title", title.clone());
    vars.insert(
        "subject",
        config.get_str_or("description", ""),
    );
    vars.insert("geometry", geometry);
    vars.insert("date", date);
    vars.insert("subtitle", subtitle);
    vars.insert("date_line", date_line);
    vars.insert("version", version);
    vars.insert("copyright", copyright);
    vars.insert("license", license);
    let mut extra = String::new();
    if config.get_bool("rendering.initials", false) {
        extra.push_str("\\n\\n% Only included if use_initials is set to true\\n\\\\usepackage{lettrine}\\n");
    }
    let chapter_name = config.get_str_or("rendering.chapter", &config.localization().get("chapter"));
    let part_name = config.get_str_or("rendering.part", &config.localization().get("part"));
    let mut chapter_names = String::new();
    if config.get_str("rendering.chapter").is_some() {
        chapter_names.push_str(&format!(
            "\\n\\\\makeatletter\\n\\\\renewcommand{{\\\\@chapapp}}{{{}}}\\n\\\\makeatother\\n\\n",
            chapter_name
        ));
    }
    if config.get_str("rendering.part").is_some() {
        chapter_names.push_str(&format!("\\n\\\\renewcommand{{\\\\partname}}{{{}}}\\n", part_name));
    }
    vars.insert("chapter_names", chapter_names);
    // body
    let mut body = String::new();
    let mut renderer = TexRenderer::new(config);
    let mut chapter_index = 0;
    for entry in &book.entries {
        match entry {
            crate::book::Entry::Part { title: part_title, .. } => {
                body.push_str(&format!(
                    "\\n\\\\setcounter{{chapter}}{{0}}\\\\part{{{}}}\\n\\\\label{{chapter-{}}}\\n",
                    escape(part_title),
                    chapter_index
                ));
                chapter_index += 1;
            }
            crate::book::Entry::Chapter { doc, .. } => {
                renderer.link_defs = doc.links.clone();
                renderer.notes_to_render = doc.notes.clone();
                renderer.first_para = true;
                body.push_str(&renderer.render_blocks(&doc.blocks));
                for (label, blocks) in renderer.notes_to_render.clone() {
                    let n = label.clone();
                    let inner = renderer.render_blocks(&blocks);
                    body.push_str(&format!("\\\\footnotetext[{}]{{{}}}", n, inner));
                }
                chapter_index += 1;
            }
        }
    }
    let _ = &renderer;
    vars.insert("body", body);
    Ok(render_template(TEMPLATE, &vars))
}

