pub fn render(book: &crate::book::Book, _errors: &mut Vec<CrowbookError>) -> Result<String, CrowbookError> {
    let config = &book.config;
    let lang = config.get_str_or("lang", "en");
    let author = config.get_str_or("author", "");
    let title = config.get_str_or("title", "");
    let class = config.get_str_or("tex.class", "book");
    let mut docclass = class.clone();
    if let Some(size) = config.get_int("tex.font.size", 0).checked(0) {
