            ("2.5cm", "1.5cm")
        } else {
            ("2cm", "2cm")
        };
        let left = config.get_str_or("tex.margin.left", left);
        let right = config.get_str_or("tex.margin.right", right);
        let top = config.get_str_or("tex.margin.top", "2cm");
        let bottom = config.get_str_or("tex.margin.bottom", "1.5cm");
        format!(
            "% Included if the stdpage option if set to false\n\\usepackage[{}, top={}, bottom={},\n  left={},right={}]{geometry} % Set dimensions/margins of the page",
            config.get_str_or("tex.paper.size", "a5paper"),
            top,
            bottom,
            left,
            right
        )
    };
    let date = config.get_str_or("date", "");
    let subtitle = config.get_str_or("subtitle", "");
    let version = match config.get_str("version") {
        Some(v) => format!("{{, {}}}", v),
        None => String::new(),
    };
    let copyright = if author.is_empty() {
        String::new()
    } else {
        String::from("\\@author")
    };
    let license = match config.get_str("license") {
        Some(l) => format!("    {{{}\\\\[5mm]}}", l),
        None => String::new(),
    };
    let date_line = if date.is_empty() {
        String::new()
    } else {
        String::from("      \\@date")
    };
    let chapter_name = config.get_str_or(
        "rendering.chapter",
        &config.localization().get("chapter"),
    );
    let part_name = config.get_str_or("rendering.part", &config.localization().get("part"));
    let mut chapter_names = String::new();
    if config.get_str("rendering.chapter").is_some() {
        chapter_names.push_str(&format!(
            "\n\\makeatletter\n\\renewcommand{{\\@chapapp}}{{{}}}\n\\makeatother\n\n",
            chapter_name
        ));
    }
    if config.get_str("rendering.part").is_some() {
        chapter_names.push_str(&format!(
            "\n\\renewcommand{{\\partname}}{{{}}}\n",
            part_name
        ));
    }
    let (has_code, has_image, has_table) = scan(&book.entries);
    let codeblock = if has_code {
        String::from(" % This part is only included if document contains code blocks\n\\usepackage{spverbatim}\n\\usepackage{color}\n\\usepackage[\n  topline=false,\n  rightline=false,\n  bottomline=false]{mdframed}\n\n\\newenvironment{mdcodeblock}{%\n  \\begin{mdframed}\n}{%\n  \\end{mdframed}\n}\n")
    } else {
        String::new()
    };
    let imageblock = if has_image {
        String::from("% Only included if document contains images\n\\usepackage{graphicx}\n\n% Standalone image\n% (an image alone in its paragraph)\n\\newcommand\\mdstandaloneimage[1]{\n  \\begin{center}\n    \\includegraphics[width=0.8\\linewidth]{#1}\n  \\end{center}\n}\n\n% Image\n% (an image embedded in a pagraph or other element)\n\\newcommand\\mdimage[1]{\\includegraphics{#1}}\n\n")
    } else {
        String::new()
    };
    let tableblock = if has_table {
        String::from("% Only included if document contains tables\n\\usepackage{tabularx}\n\n% Table environment\n% Crowbook currently always insert \\hline at beginning and end of the table\n\n\n\\newenvironment{mdtable}[1]{%\n  \\center\n  \\tabularx{\\textwidth}{#1}\n  \\hline\n}{%\n  \\endtabularx\n  \\endcenter\\n}\n\\n")
    } else {
        String::new()
    };
    let mut body = String::new();
    let mut renderer = TexRenderer::new(config);
    let mut chapter_index = 0;
    for entry in &book.entries {
        match entry {
            crate::book::Entry::Part { title: part_title, .. } => {
                body.push_str(&format!(
                    "\n\\setcounter{{chapter}}{{0}}\\part{{{}}}\n\\label{{chapter-{}}}\n",
                    escape(part_title),
                    chapter_index
                ));
                chapter_index += 1;
            }
            crate::book::Entry::Chapter { doc, .. } => {
                renderer.link_defs = doc.links.clone();
                renderer.notes_to_render = doc.notes.clone();
                renderer.first_para = true;
                body.push_str(&renderer.render_blocks(&doc.blocks));
                for (label, blocks) in renderer.notes_to_render.clone() {
                    let inner = renderer.render_blocks(&blocks);
                    body.push_str(&format!("\\footnotetext[{}]{{{}}}", label, inner));
                }
                chapter_index += 1;
            }
        }
    }
    let mut vars: HashMap<&str, String> = HashMap::new();
    vars.insert("docclass", docclass);
    vars.insert("babel", babel.to_string());
    vars.insert("author", author);
    vars.insert("title", title);
    vars.insert("subject", config.get_str_or("description", ""));
    vars.insert("geometry", geometry);
    vars.insert("date", date);
    vars.insert("subtitle", subtitle);
    vars.insert("date_line", date_line);
    vars.insert("version", version);
    vars.insert("copyright", copyright);
    vars.insert("license", license);
    vars.insert("chapter_names", chapter_names);
    vars.insert("codeblock", codeblock);
    vars.insert("imageblock", imageblock);
    vars.insert("tableblock", tableblock);
    vars.insert("body", body);
    Ok(render_template(TEMPLATE, &vars))
}

