{"command": "cat > src/lib/render/epub.rs <<'RSEOF'
//! Rendering to EPUB.

use crate::config::{Config, CrowbookError};
use crate::render::html::{base64, escape_attr, mime_of, Renderer};
use crate::render::template::render as render_template;
use std::collections::HashMap;

const EPUB_CSS: &str = include_str!("../../assets/epub.css");

/// The XHTML head of a chapter file.
fn xhtml_head(title: &str, lang: &str) -> String {
    let mut out = String::new();
    out.push_str("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
    out.push_str("<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.1//EN\" \"http://www.w3.org/TR/xhtml11/DTD/xhtml11.dtd\">\n");
    out.push_str(&format!(
        "<html xmlns=\"http://www.w3.org/1999/xhtml\" xml:lang=\"{lang}\" lang=\"{lang}\">\n"
    ));
    out.push_str("  <head>\n");
    out.push_str("  <meta http-equiv=\"Content-Type\" content=\"text/html; charset=utf-8\" />\n");
    out.push_str("  <meta http-equiv=\"Content-Style-Type\" content=\"text/css\" />\n");
    out.push_str("  <meta name=\"generator\" content=\"crowbook\" />\n");
    out.push_str(&format!("  <title>{}</title>\n", escape_attr(title)));
    out.push_str("  <link rel=\"stylesheet\" type=\"text/css\" href=\"stylesheet.css\" />\n");
    out.push_str("  </head>\n");
    out.push_str(&format!(
        "  <body xml:lang=\"{lang}\" lang=\"{lang}\">\n"
    ));
    out
}

fn epub_css(config: &Config) -> String {
    let lang = config.get_str_or("lang", "en");
    let mut vars: HashMap<&str, String> = HashMap::new();
    vars.insert("lang", lang);
    vars.insert("additional_code", config.get_str_or("epub.css.add", ""));
    vars.insert(
        "colors",
        render_template(include_str!("../../assets/colors.css"), &vars),
    );
    render_template(EPUB_CSS, &vars)
}

/// A file of the EPUB.
struct File {
    name: String,
    content: Vec<u8>,
    mime: &'static str,
    itemref: bool,
    cover: bool,
    reftype: Option<&'static str>,
    title: String,
}

/// Renders the book to EPUB (returns the zip archive).
pub fn render(book: &crate::book::Book, _errors: &mut Vec<CrowbookError>) -> Result<Vec<u8>, CrowbookError> {
    let config = &book.config;
    let lang = config.get_str_or("lang", "en");
    let author = config.get_str_or("author", "");
    let title = config.get_str_or("title", "");
    let l10n = config.render_l10n();
    let version = config.get_int("epub.version", 2);
    let mut files: Vec<File> = Vec::new();
    let mut images: Vec<(String, Vec<u8>)> = Vec::new();
    let toc_entries = crate::book::toc(config, &book.entries, &crate::book::chapter_links(config, &book.entries));
    // the toc titles
    let mut titles: Vec<String> = Vec::new();
    fn flat_titles(items: &[crate::book::TocEntry], out: &mut Vec<String>) {
        for i in items {
            out.push(i.title.clone());
            flat_titles(&i.children, out);
        }
    }
    flat_titles(&toc_entries, &mut titles);
    let mut idx = 0;
    let mut renderer = Renderer::new(config, true, false, book.files(), 0);
    renderer.link = 1;
    // title page
    {
        let mut head = xhtml_head(&title, &lang);
        head.push_str("    <div id = \"page\">\n");
        head.push_str(&format!(
            "  <h2 class=\"author\">{}</h2>\n",
            escape_attr(&author)
        ));
        head.push_str(&format!(
            "  <h1 class=\"title\">{}</h1>\n",
            escape_attr(&title)
        ));
        if let Some(s) = config.get_str("subtitle") {
            head.push_str(&format!(
                "  <h2 class=\"subtitle\">{}</h2>\n",
                escape_attr(&s)
            ));
        }
        head.push_str("  \n</body>\n</html>\n");
        files.push(File {
            name: "title_page.xhtml".to_string(),
            content: head.into_bytes(),
            mime: "application/xhtml+xml",
            itemref: true,
            cover: false,
            reftype: Some("TitlePage"),
            title: l10n.get("title"),
        });
    }
    // chapters
    for entry in &book.entries {
        match entry {
            crate::book::Entry::Part { title: part_title, number } => {
                let part_name =
                    config.get_str_or("rendering.part", &l10n.get("part"));
                let number_str = if config.get_bool("rendering.part.roman_numerals", true) {
                    crate::book::roman(*number)
                } else {
                    number.to_string()
                };
                let link = renderer.link;
                renderer.link += 1;
                let toc_title = titles.get(idx).cloned().unwrap_or_default();
                idx += 1;
                let mut content = format!("      <h2 class = 'part'>{} {}</h2> <h1 id = 'link-{}' class = 'part'>{}</h1>\n", escape_attr(&part_name), escape_attr(&number_str), link, escape_attr(part_title));
                let name = format!("chapter_{:03}.xhtml", files.len() - 1);
                let head = xhtml_head(&toc_title, &lang);
                let mut x = head;
                x.push_str("    <div id = \"page\">\n");
                x.push_str(&content);
                x.push_str("    </div>\n  </body>\n</html>\n");
                files.push(File {
                    name,
                    content: x.into_bytes(),
                    mime: "application/xhtml+xml",
                    itemref: true,
                    cover: false,
                    reftype: Some("Text"),
                    title: toc_title,
                });
                renderer.para += 1;
            }
            crate::book::Entry::Chapter { doc, name, .. } => {
                renderer.source = name.clone();
                renderer.note_counter = 0;
                renderer.link_defs = doc.links.clone();
