fn count_headings(blocks: &[crate::parser::Block]) -> usize {
    let mut n = 0;
    for block in blocks {
        if let crate::parser::Block::Heading { .. } = block {
            n += 1;
        }
    }
    n
}

/// Renders the blocks of a chapter to XHTML, splitting the level-1 headings
/// with a `\u{1}` separator.
fn render_chapter_xhtml(
    config: &Config,
    renderer: &mut Renderer,
    doc: &crate::parser::Doc,
    images: &mut Vec<(String, Vec<u8>)>,
) -> String {
    let chapter_name = config.get_str_or("rendering.chapter", &config.render_l10n().get("chapter"));
    let num_depth = config.get_int("rendering.num_depth", 1);
    let mut out = String::new();
    for block in &doc.blocks {
        match block {
            crate::parser::Block::Heading { level: 1, inline } => {
                if !out.is_empty() {
                    out.push('\u{1}');
                }
                renderer.chapter_number += 1;
                let number = if num_depth >= 1 {
                    renderer.chapter_number
                } else {
                    0
                };
                let title = crate::book::heading_text(inline);
                let link = renderer
                    .chapter_links
                    .first()
                    .copied()
                    .unwrap_or(renderer.link);
                if !renderer.chapter_links.is_empty() {
                    renderer.chapter_links.remove(0);
                }
                let _ = link;
                let mut h = format!("<h1 id = 'link-{}'>", renderer.link);
                renderer.link += 1;
                if number > 0 {
                    h.push_str(&format!(
                        "<span class = 'chapter-header'>{} {}</span>",
                        escape_attr(&chapter_name),
                        number
                    ));
                    if !title.is_empty() {
                        h.push_str("<br />");
                    }
                }
                h.push_str(&escape_attr(&title));
                h.push_str("</h1>");
                out.push_str(&h);
            }
            other => out.push_str(&renderer.render_block(other)),
        }
    }
    out.push_str(&renderer.render_notes());
    // copy the images
    for img in renderer.images.clone() {
        let parts: Vec<&str> = img.split('|').collect();
        if let Some(data) = std::fs::read(&parts[1]).ok() {
            images.push((parts[0].to_string(), data));
        }
    }
    renderer.images.clear();
    out
}

