            escape_attr(&author)
        ));
        head.push_str(&format!(
            "  <h1 class=\"title\">{}</h1>\n",
            escape_attr(&title)
        ));
        if let Some(s) = config.get_str("subtitle") {
            head.push_str(&format!(
                "  <h2 class=\"subtitle\">{}</h2>\n",
                escape_attr(&s)
            ));
        }
