                    })
                    .map(|(j, _)| i + 1 + j)
                    .collect()
            } else {
                Vec::new()
            };
            if children.is_empty() {
                out.push_str(&format!(
                    "{pad}<li><a href=\\"{}\\">{}</a></li>\\n",
                    f.name,
                    escape_attr(&f.title)
                ));
            } else {
                out.push_str(&format!("{pad}<li>\\n"));
                out.push_str(&format!(
                    "{pad}  <a href=\\"{}\\">{}</a>\\n",
                    f.name,
                    escape_attr(&f.title)
                ));
