                    ));
                }
                out.push_str(&format!("{pad}  </{tag}>\\n"));
                out.push_str(&format!("{pad}</li>\\n"));
            }
        }
    }
    let is_part: Vec<bool> = files.iter().map(|f| f.reftype == Some("Part")).collect();
    write_list(&files, &mut nav, "ol", 6, &is_part);
